// ════════════════════════════════════════════════════════
//  CRONOGRAMA DE OBRAS — Sprint 2 (Gantt + dependências)
// ════════════════════════════════════════════════════════

const STORAGE_KEY = 'oreon_cronograma_v2';

// ── Sprint 3: Cascade recalculation ──
function cascadeRecalc() {
  const taskMap = {};
  state.tasks.forEach(t => { taskMap[t.id] = t; });

  // Build holiday set for all years spanned
  const allYears = new Set();
  state.tasks.forEach(t => {
    if (t.start) allYears.add(new Date(t.start).getFullYear());
    if (t.end)   allYears.add(new Date(t.end).getFullYear());
  });
  allYears.add(new Date().getFullYear());
  const hs = buildHolidaySet([...allYears]);

  let changed = true;
  let passes = 0;
  while (changed && passes < 20) {
    changed = false;
    passes++;
    state.tasks.forEach(task => {
      if (!task.predecessors) return;
      const predIds = task.predecessors.toString().split(',').map(s => parseInt(s.trim())).filter(Boolean);
      if (!predIds.length) return;
      // find latest end among predecessors
      let latestEnd = null;
      predIds.forEach(pid => {
        const p = taskMap[pid];
        if (p && p.end) {
          const pEnd = new Date(p.end);
          if (!latestEnd || pEnd > latestEnd) latestEnd = pEnd;
        }
      });
      if (!latestEnd) return;
      // Only move if predecessor end > current task start
      const curStart = task.start ? new Date(task.start) : null;
      if (!curStart || latestEnd > curStart) {
        // New start = next work day after latestEnd
        const newStart = new Date(latestEnd);
        newStart.setDate(newStart.getDate() + 1);
        newStart.setHours(8, 0, 0, 0);
        // Skip weekends and holidays
        while (isWeekend(newStart) || hs.has(dateKey(newStart))) {
          newStart.setDate(newStart.getDate() + 1);
        }
        const newEnd = addWorkDays(newStart.toISOString(), task.duration || 1, hs);
        const newStartISO = newStart.toISOString();
        if (newStartISO !== task.start || newEnd !== task.end) {
          task.start = newStartISO;
          task.end = newEnd;
          taskMap[task.id] = task;
          changed = true;
        }
      }
    });
  }
  save();
}

// ── Sprint 5: Undo buffer ──
let _deletedBuffer = [];

