// ── Logo Hagana Tecnologia (base64 PNG) ──
const HAGANA_LOGO_B64 = 'data:image/png;base64,';

// ── Feriados nacionais BR (MM-DD fixos + Páscoa variável) ──
const FERIADOS_FIXOS = new Set([
  '01-01','04-21','05-01','09-07','10-12','11-02','11-15','11-20','12-25'
]);
// Páscoa pelo algoritmo de Gauss — gera datas ISO p/ ±3 anos
function gerarPascoa(ano) {
  const a = ano % 19, b = Math.floor(ano/100), c = ano % 100;
  const d = Math.floor(b/4), e = b % 4, f = Math.floor((b+8)/25);
  const g = Math.floor((b-f+1)/3), h = (19*a+b-d-g+15) % 30;
  const i = Math.floor(c/4), k = c % 4;
  const l = (32+2*e+2*i-h-k) % 7;
  const m = Math.floor((a+11*h+22*l)/451);
  const mes = Math.floor((h+l-7*m+114)/31);
  const dia = ((h+l-7*m+114) % 31) + 1;
  const p = new Date(ano, mes-1, dia);
  // Sexta-feira Santa = Páscoa - 2; Corpus Christi = Páscoa + 60
  return [
    new Date(p.getTime() - 2*864e5),
    p,
    new Date(p.getTime() + 60*864e5),
  ];
}
function buildHolidaySet(anos) {
  const s = new Set();
  anos.forEach(ano => {
    FERIADOS_FIXOS.forEach(mmdd => s.add(`${ano}-${mmdd}`));
    gerarPascoa(ano).forEach(d => s.add(d.toISOString().slice(0,10)));
  });
  return s;
}

function isWeekend(date) { const d = date.getDay(); return d === 0 || d === 6; }
function dateKey(date) { return date.toISOString().slice(0,10); }

// ── Estado ──
let state = { projectName: '', supervisorName: '', tasks: [], nextId: 1, relatorios: [], relNextId: 1 };
let editingId = null;
let selectedId = null;
let DAY_W = 28; // px por dia — zoom
const ROW_H = 36;
const HDR_H = 52; // header do gantt (mês + dia)
const BAR_PAD = 6; // padding vertical da barra

// ── $ helpers ──
const $ = (s, c = document) => c.querySelector(s);
const $$ = (s, c = document) => [...c.querySelectorAll(s)];

const projectNameEl = $('#project-name');
const taskBodyEl    = $('#task-body');
const emptyStateEl  = $('#empty-state');
const modalOverlay  = $('#modal-overlay');
const statTasks     = $('#stat-tasks');
const statDuration  = $('#stat-duration');
const statRange     = $('#stat-range');
const toastEl       = $('#toast');
const fileInput     = $('#file-input');
const tooltipEl     = $('#gantt-tooltip');
const ganttBodyWrap = $('#gantt-body-wrap');
const ganttSvg      = $('#gantt-svg');
const ganttHdrSvg   = $('#gantt-hdr-svg');

// ── Persistência ──
function save() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    const now = new Date();
    const hhmm = String(now.getHours()).padStart(2,'0') + ':' + String(now.getMinutes()).padStart(2,'0');
    const el = document.getElementById('save-time');
    if (el) el.textContent = '💾 Salvo às ' + hhmm;
  } catch(e) {}
  if (window.Cloud && Cloud.queueSave) Cloud.queueSave();
}
function load() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      state = { ...state, ...JSON.parse(raw) };
      projectNameEl.value = state.projectName;
      if (state.supervisorName) $('#supervisor-name').value = state.supervisorName;
      if (!state.relatorios) state.relatorios = [];
      if (!state.relNextId) state.relNextId = 1;
    }
  } catch(e) {}
}

// ── Toast ──
let toastT;
function toast(msg, ms = 2200) {
  toastEl.textContent = msg; toastEl.classList.add('show');
  clearTimeout(toastT); toastT = setTimeout(() => toastEl.classList.remove('show'), ms);
}

// ── Datas ──
function fmtDate(iso) {
  if (!iso) return '—';
  const d = new Date(iso); if (isNaN(d)) return iso;
  return `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`;
}
function fmtDatetime(iso) {
  if (!iso) return '—';
  const d = new Date(iso); if (isNaN(d)) return iso;
  const dd = String(d.getDate()).padStart(2,'0');
  const mm = String(d.getMonth()+1).padStart(2,'0');
  const hh = String(d.getHours()).padStart(2,'0');
  const mi = String(d.getMinutes()).padStart(2,'0');
  return `${dd}/${mm}/${d.getFullYear()} ${hh}:${mi}`;
}
function toInput(iso) {
  if (!iso) return '';
  const d = new Date(iso); if (isNaN(d)) return '';
  const p = n => String(n).padStart(2,'0');
  return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`;
}
function addWorkDays(isoStart, days, holidaySet) {
  const d = new Date(isoStart);
  let added = 0;
  while (added < days - 1) {
    d.setDate(d.getDate() + 1);
    if (!isWeekend(d) && !holidaySet.has(dateKey(d))) added++;
  }
  d.setHours(17, 0, 0, 0);
  return d.toISOString();
}

function recalcEnd() {
  const start = $('#f-start').value;
  const dur = parseInt($('#f-dur').value) || 1;
  if (!start) return;
  const anos = [new Date().getFullYear(), new Date().getFullYear()+1];
  const hs = buildHolidaySet(anos);
  $('#f-end').value = toInput(addWorkDays(start, dur, hs));
}

// ── Render tabela ──
function statusDot(t) {
  const pct = t.percentComplete || 0;
  const cls = pct >= 100 ? 'sd-done' : pct > 0 ? 'sd-progress' : 'sd-none';
  return `<span class="status-dot ${cls}"></span>`;
}

function render() {
  const tasks = state.tasks;
  emptyStateEl.hidden = tasks.length > 0;

  taskBodyEl.innerHTML = tasks.map((t, i) => `
    <tr data-id="${t.id}" tabindex="0" class="${t.id === selectedId ? 'selected' : ''}">
      <td>${i+1}</td>
      <td class="name-cell" title="${t.name}">${t.name}</td>
      <td class="dur-cell">${t.duration}d</td>
      <td class="date-cell">${fmtDate(t.start)}</td>
      <td class="date-cell">${fmtDate(t.end)}</td>
      <td class="ant-cell">${t.predecessors || '—'}</td>
      <td class="act-cell">
        <div class="row-actions">
          <button class="icon-btn" data-action="edit" data-id="${t.id}" title="Editar">✏️</button>
          <button class="icon-btn danger" data-action="del" data-id="${t.id}" title="Excluir">🗑</button>
        </div>
      </td>
    </tr>`).join('');

  updateStatusBar();
  renderGantt();
  save();
}

function updateStatusBar() {
  const tasks = state.tasks;
  statTasks.textContent = `${tasks.length} tarefa${tasks.length!==1?'s':''}`;
  const tot = tasks.reduce((a,t) => a+(t.duration||0), 0);
  statDuration.textContent = tot ? `${tot} dias úteis` : '—';
  const s = tasks.map(t=>t.start).filter(Boolean).map(x=>new Date(x).getTime());
  const e = tasks.map(t=>t.end).filter(Boolean).map(x=>new Date(x).getTime());
  if (s.length && e.length) {
    const fmt = d=>`${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`;
    statRange.textContent = `${fmt(new Date(Math.min(...s)))} → ${fmt(new Date(Math.max(...e)))}`;
  } else { statRange.textContent = '—'; }
}

// ══════════════════════════════════════
//  GANTT SVG RENDERER
// ══════════════════════════════════════

function renderGantt() {
  const tasks = state.tasks;
  if (!tasks.length) { ganttSvg.innerHTML = ''; ganttHdrSvg.innerHTML = ''; return; }

  // Calcular janela de datas
  const starts = tasks.map(t => t.start).filter(Boolean).map(x => new Date(x));
  const ends   = tasks.map(t => t.end).filter(Boolean).map(x => new Date(x));
  if (!starts.length) return;

  let minDate = new Date(Math.min(...starts));
  let maxDate = new Date(Math.max(...ends));

  // Adicionar margem de 3 dias em cada extremo
  minDate.setDate(minDate.getDate() - 3);
  maxDate.setDate(maxDate.getDate() + 5);

  // Normalizar para início do dia
  minDate.setHours(0, 0, 0, 0);
  maxDate.setHours(23, 59, 59, 999);

  const totalDays = Math.ceil((maxDate - minDate) / 864e5);
  const anos = [];
  for (let y = minDate.getFullYear(); y <= maxDate.getFullYear(); y++) anos.push(y);
  const holidaySet = buildHolidaySet(anos);

  const W = totalDays * DAY_W;
  const H = tasks.length * ROW_H;
  const today = new Date(); today.setHours(0,0,0,0);

  // Helper: x de uma data
  function dateToX(date) {
    return ((new Date(date) - minDate) / 864e5) * DAY_W;
  }

  // CSS vars resolvidos
  const cs = getComputedStyle(document.documentElement);
  const C = {
    grid:    cs.getPropertyValue('--gantt-grid').trim(),
    weekend: cs.getPropertyValue('--gantt-weekend').trim(),
    holiday: cs.getPropertyValue('--gantt-holiday').trim(),
    today:   cs.getPropertyValue('--gantt-today').trim(),
    bar:     cs.getPropertyValue('--gantt-bar').trim(),
    barTxt:  cs.getPropertyValue('--gantt-bar-txt').trim(),
    dep:     cs.getPropertyValue('--gantt-dep').trim(),
    hdrTxt:  cs.getPropertyValue('--gantt-hdr-txt').trim(),
    hdrBg:   cs.getPropertyValue('--gantt-hdr').trim(),
    surface: cs.getPropertyValue('--surface').trim(),
    text2:   cs.getPropertyValue('--text-2').trim(),
    text3:   cs.getPropertyValue('--text-3').trim(),
    border:  cs.getPropertyValue('--border').trim(),
  };

  // ── SVG Header (meses + dias) ──
  ganttHdrSvg.setAttribute('width', W);
  ganttHdrSvg.setAttribute('height', HDR_H);
  ganttHdrSvg.setAttribute('viewBox', `0 0 ${W} ${HDR_H}`);
  ganttHdrSvg.style.minWidth = W + 'px';

  const PT_MESES = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
  const PT_DIAS  = ['D','S','T','Q','Q','S','S'];

  let hdrSVG = `<rect width="${W}" height="${HDR_H}" fill="${C.hdrBg}"/>`;

  // Linha de meses (faixa superior, H=22px)
  let curMonth = -1, monthStart = 0;
  function closeMonth(x) {
    if (curMonth < 0) return;
    const mw = x - monthStart;
    const d = new Date(minDate); d.setDate(d.getDate() + Math.round(monthStart/DAY_W));
    const label = `${PT_MESES[d.getMonth()]} ${d.getFullYear()}`;
    hdrSVG += `<rect x="${monthStart}" y="0" width="${mw}" height="22" fill="${C.hdrBg}" stroke="${C.grid}" stroke-width="0.5"/>`;
    hdrSVG += `<text x="${monthStart + mw/2}" y="15" text-anchor="middle" font-size="11" font-weight="600" fill="${C.hdrTxt}" font-family="Inter,system-ui">${label}</text>`;
  }

  // Faixa de dias (linhas 22→52, H=30px)
  for (let i = 0; i < totalDays; i++) {
    const d = new Date(minDate); d.setDate(d.getDate() + i);
    const x = i * DAY_W;
    const mo = d.getMonth();
    if (mo !== curMonth) { closeMonth(x); curMonth = mo; monthStart = x; }

    const isWe = isWeekend(d);
    const isHol = holidaySet.has(dateKey(d));
    const isToday = dateKey(d) === dateKey(today);

    // Fundo dia
    let dayFill = 'none';
    if (isHol)    dayFill = C.holiday;
    else if (isWe) dayFill = C.weekend;
    if (dayFill !== 'none')
      hdrSVG += `<rect x="${x}" y="22" width="${DAY_W}" height="30" fill="${dayFill}"/>`;
    if (isToday)
      hdrSVG += `<rect x="${x}" y="22" width="${DAY_W}" height="30" fill="${C.today}"/>`;

    // Número do dia
    const dayColor = isToday ? C.bar : (isWe||isHol) ? C.text3 : C.hdrTxt;
    const fw = isToday ? '700' : (isWe||isHol) ? '400' : '500';
    hdrSVG += `<text x="${x+DAY_W/2}" y="40" text-anchor="middle" font-size="9.5" font-weight="${fw}" fill="${dayColor}" font-family="Inter,system-ui">${d.getDate()}</text>`;
    // Letra do dia da semana
    hdrSVG += `<text x="${x+DAY_W/2}" y="50" text-anchor="middle" font-size="8" fill="${C.text3}" font-family="Inter,system-ui">${PT_DIAS[d.getDay()]}</text>`;

    // Linha vertical
    hdrSVG += `<line x1="${x}" y1="22" x2="${x}" y2="${HDR_H}" stroke="${C.grid}" stroke-width="0.5"/>`;
  }
  closeMonth(W);
  // Borda inferior header
  hdrSVG += `<line x1="0" y1="${HDR_H}" x2="${W}" y2="${HDR_H}" stroke="${C.grid}" stroke-width="1"/>`;
  ganttHdrSvg.innerHTML = hdrSVG;

  // ── SVG Body ──
  ganttSvg.setAttribute('width', W);
  ganttSvg.setAttribute('height', H);
  ganttSvg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  ganttSvg.style.minWidth = W + 'px';

  let svg = '';

  // Fundo + grid de dias
  svg += `<rect width="${W}" height="${H}" fill="${C.surface}"/>`;

  for (let i = 0; i < totalDays; i++) {
    const d = new Date(minDate); d.setDate(d.getDate() + i);
    const x = i * DAY_W;
    const isWe = isWeekend(d);
    const isHol = holidaySet.has(dateKey(d));
    const isToday = dateKey(d) === dateKey(today);

    if (isHol)    svg += `<rect x="${x}" y="0" width="${DAY_W}" height="${H}" fill="${C.holiday}"/>`;
    else if (isWe) svg += `<rect x="${x}" y="0" width="${DAY_W}" height="${H}" fill="${C.weekend}"/>`;
    if (isToday)   svg += `<rect x="${x}" y="0" width="${DAY_W}" height="${H}" fill="${C.today}"/>`;
    svg += `<line x1="${x}" y1="0" x2="${x}" y2="${H}" stroke="${C.grid}" stroke-width="0.5"/>`;
  }

  // Linhas horizontais das tarefas
  tasks.forEach((t, i) => {
    const y = i * ROW_H;
    svg += `<line x1="0" y1="${y+ROW_H}" x2="${W}" y2="${y+ROW_H}" stroke="${C.grid}" stroke-width="0.5"/>`;
    // Fundo linha selecionada (destacado por tom)
    if (t.id === selectedId)
      svg += `<rect x="0" y="${y}" width="${W}" height="${ROW_H}" fill="rgba(37,99,235,0.07)"/>`;
  });

  // ── Linhas de dependência (FS) ──
  const taskMap = {};
  tasks.forEach((t, i) => { taskMap[t.id] = { t, i }; });

  svg += `<g id="dep-lines">`;
  tasks.forEach((task, i) => {
    if (!task.predecessors || !task.end) return;
    const preds = task.predecessors.toString().split(',').map(s => parseInt(s.trim())).filter(Boolean);
    preds.forEach(pid => {
      const pred = tasks.find(x => x.id === pid);
      if (!pred || !pred.end || !task.start) return;

      const pi = tasks.indexOf(pred);
      // X de saída: fim do predecessor
      const x1 = dateToX(pred.end);
      // Y de saída: meio da linha do predecessor
      const y1 = pi * ROW_H + ROW_H / 2;
      // X de entrada: início da tarefa atual
      const x2 = dateToX(task.start);
      // Y de entrada: meio da linha atual
      const y2 = i * ROW_H + ROW_H / 2;

      // Seta em L: horizontal→desce/sobe→horizontal
      const midX = x1 + Math.max(8, (x2-x1)/2);
      const path = `M${x1},${y1} L${midX},${y1} L${midX},${y2} L${x2},${y2}`;
      svg += `<path d="${path}" fill="none" stroke="${C.dep}" stroke-width="1.5" stroke-dasharray="4,2" marker-end="url(#arrow)"/>`;
    });
  });
  svg += `</g>`;

  // ── Barras ──
  svg += `<defs>
    <marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto">
      <polygon points="0 0, 7 3.5, 0 7" fill="${C.dep}"/>
    </marker>
    <filter id="bar-shadow" x="-5%" y="-10%" width="110%" height="130%">
      <feDropShadow dx="0" dy="1" stdDeviation="1.5" flood-color="rgba(0,0,0,0.18)"/>
    </filter>
  </defs>`;

  tasks.forEach((task, i) => {
    if (!task.start || !task.end) return;
    const x = dateToX(task.start);
    const x2 = dateToX(task.end);
    const bw = Math.max(DAY_W * 0.5, x2 - x);
    const y = i * ROW_H + BAR_PAD;
    const bh = ROW_H - BAR_PAD * 2;
    const isSelected = task.id === selectedId;

    // Sombra + barra principal
    const barOpacity = isSelected ? '1' : '0.92';
    const pctT = Math.max(0, Math.min(100, task.percentComplete || 0));
    const barColor = pctT >= 100 ? '#16a34a' : C.bar;
    const strokeColor = isSelected ? '#1d4ed8' : 'none';
    const strokeW = isSelected ? '2' : '0';

    svg += `<rect
      x="${x}" y="${y}" width="${bw}" height="${bh}"
      rx="3" ry="3"
      fill="${barColor}" fill-opacity="${barOpacity}"
      stroke="${strokeColor}" stroke-width="${strokeW}"
      filter="url(#bar-shadow)"
      data-id="${task.id}"
      style="cursor:pointer"
    />`;
    if (pctT > 0 && pctT < 100) {
      svg += `<rect x="${x}" y="${y}" width="${bw * pctT / 100}" height="${bh}" rx="3" ry="3" fill="#0b1f5c" fill-opacity="0.45" pointer-events="none"/>`;
    }

    // Duração label dentro da barra
    const label = pctT > 0 ? `${pctT}%` : `${task.duration}d`;
    const labelX = x + bw / 2;
    const labelY = y + bh / 2 + 4;
    if (bw > 22) {
      svg += `<text x="${labelX}" y="${labelY}" text-anchor="middle"
        font-size="10" font-weight="600" fill="${C.barTxt}"
        font-family="Inter,system-ui" pointer-events="none">${label}</text>`;
    }

    // Nome fora da barra (à direita) se couber
    if (bw < W * 0.3) {
      const nameX = x + bw + 6;
      const maxChars = Math.max(10, Math.floor((W - nameX) / 7));
      const shortName = task.name.length > maxChars ? task.name.slice(0, maxChars) + '…' : task.name;
      svg += `<text x="${nameX}" y="${labelY}" font-size="10.5" font-weight="500"
        fill="${C.text2}" font-family="Inter,system-ui" pointer-events="none">${shortName}</text>`;
    }
  });

  // Linha de hoje
  const todayX = dateToX(today) + DAY_W / 2;
  svg += `<line x1="${todayX}" y1="0" x2="${todayX}" y2="${H}" stroke="${C.bar}" stroke-width="1.5" stroke-dasharray="4,3" opacity="0.7"/>`;

  ganttSvg.innerHTML = svg;

  // Tamanho do wrapper
  $('#gantt-svg-wrap').style.width  = W + 'px';
  $('#gantt-svg-wrap').style.height = H + 'px';

  // Sincronizar scroll header ↔ body
  ganttBodyWrap.onscroll = () => {
    ganttHdrSvg.parentElement.scrollLeft = ganttBodyWrap.scrollLeft;
  };
  $('#gantt-header').style.overflowX = 'hidden';

  // ── Tooltip e click nas barras ──
  ganttSvg.addEventListener('mousemove', onGanttMove);
  ganttSvg.addEventListener('mouseleave', () => tooltipEl.classList.remove('show'));
  ganttSvg.addEventListener('click', onGanttClick);
}

function onGanttMove(e) {
  const rect = e.target.closest('rect[data-id]');
  if (!rect) { tooltipEl.classList.remove('show'); return; }
  const id = parseInt(rect.dataset.id);
  const task = state.tasks.find(t => t.id === id);
  if (!task) return;

  const idx = state.tasks.indexOf(task);
  tooltipEl.innerHTML = `<strong>${idx+1}. ${task.name}</strong>
    ⏱ Duração: ${task.duration} dias úteis<br>
    📅 Início: ${fmtDatetime(task.start)}<br>
    🏁 Fim: ${fmtDatetime(task.end)}<br>
    ${task.predecessors ? '⬅ Antec.: #' + task.predecessors : ''}`;

  tooltipEl.style.left = (e.clientX + 14) + 'px';
  tooltipEl.style.top  = (e.clientY - 10) + 'px';
  tooltipEl.classList.add('show');
}

function onGanttClick(e) {
  const rect = e.target.closest('rect[data-id]');
  if (!rect) return;
  const id = parseInt(rect.dataset.id);
  selectedId = (selectedId === id) ? null : id;
  // Sincroniza seleção na tabela
  $$('tr[data-id]').forEach(tr => {
    tr.classList.toggle('selected', parseInt(tr.dataset.id) === selectedId);
  });
  // Scroll na tabela para linha selecionada
  if (selectedId) {
    const row = $(`tr[data-id="${selectedId}"]`);
    if (row) row.scrollIntoView({ block: 'nearest' });
  }
  renderGantt();
}

// ── Modal ──
function openModal(id = null) {
  editingId = id;
  $('#modal-title').textContent = id === null ? 'Nova Tarefa' : 'Editar Tarefa';
  $('#modal-save').textContent  = id === null ? '💾 Adicionar' : '💾 Salvar';

  // Switch to first tab
  document.querySelectorAll('.modal-tab').forEach(tb => tb.classList.remove('active'));
  document.querySelectorAll('.tab-panel').forEach(tp => tp.classList.remove('active'));
  document.querySelector('.modal-tab[data-tab="tab-geral"]').classList.add('active');
  document.getElementById('tab-geral').classList.add('active');

  if (id !== null) {
    const t = state.tasks.find(x => x.id === id);
    if (!t) return;
    $('#f-name').value  = t.name;
    $('#f-dur').value   = t.duration;
    $('#f-start').value = toInput(t.start);
    $('#f-end').value   = toInput(t.end);
    $('#f-notes').value = t.notes || '';
    $('#f-color').value = t.color || '#2563eb';
    $('#f-pct').value   = t.percentComplete || 0;
    $('#f-pct-val').textContent = (t.percentComplete || 0) + '%';
    $('#f-resp').value  = t.responsible || '';
    $('#f-type').value  = t.taskType || 'normal';
    toggleMarcoHint();
  } else {
    $('#f-name').value  = '';
    $('#f-dur').value   = '5';
    $('#f-notes').value = '';
    $('#f-color').value = '#2563eb';
    $('#f-pct').value   = 0;
    $('#f-pct-val').textContent = '0%';
    $('#f-resp').value  = '';
    $('#f-type').value  = 'normal';
    $('#marco-hint').style.display = 'none';
    const now = new Date(); now.setDate(now.getDate()+1); now.setHours(8,0,0,0);
    $('#f-start').value = toInput(now.toISOString());
    recalcEnd();
  }

  // Build predecessor checkboxes
  const predList = document.getElementById('pred-list');
  const otherTasks = state.tasks.filter(x => x.id !== id);
  if (!otherTasks.length) {
    predList.innerHTML = '<span style="color:var(--text-3);font-size:12px;">Nenhuma tarefa disponível</span>';
  } else {
    const currentTask = id !== null ? state.tasks.find(x => x.id === id) : null;
    const currentPreds = currentTask && currentTask.predecessors
      ? currentTask.predecessors.toString().split(',').map(s => parseInt(s.trim())).filter(Boolean)
      : [];
    predList.innerHTML = otherTasks.map((t, i) => {
      const checked = currentPreds.includes(t.id) ? 'checked' : '';
      return `<label class="pred-item"><input type="checkbox" data-pred-id="${t.id}" ${checked}/> #${i+1} ${t.name}</label>`;
    }).join('');
  }

  modalOverlay.hidden = false;
  setTimeout(() => $('#f-name').focus(), 50);
}

function toggleMarcoHint() {
  const isMarco = $('#f-type').value === 'marco';
  $('#marco-hint').style.display = isMarco ? 'block' : 'none';
  if (isMarco) $('#f-dur').value = 0;
}

function closeModal() { modalOverlay.hidden = true; editingId = null; }

function saveModal() {
  const name  = $('#f-name').value.trim().toUpperCase();
  const typeVal = $('#f-type').value;
  const dur   = typeVal === 'marco' ? 0 : (parseInt($('#f-dur').value) || 1);
  const start = $('#f-start').value ? new Date($('#f-start').value).toISOString() : null;
  const end   = $('#f-end').value   ? new Date($('#f-end').value).toISOString()   : null;
  const notes = $('#f-notes').value.trim();
  const color = $('#f-color').value;
  const pct   = parseInt($('#f-pct').value) || 0;
  const resp  = $('#f-resp').value.trim();

  // Read predecessors from checkboxes
  const checkedPreds = [...document.querySelectorAll('#pred-list input[type=checkbox]:checked')]
    .map(cb => cb.dataset.predId).filter(Boolean);
  const ant = checkedPreds.join(',');

  if (!name) { $('#f-name').focus(); toast('⚠️ Informe o nome da tarefa'); return; }

  if (editingId === null) {
    state.tasks.push({ id: state.nextId++, name, duration: dur, predecessors: ant, start, end,
      notes, color, percentComplete: pct, responsible: resp, taskType: typeVal });
    toast('✅ Tarefa adicionada');
  } else {
    const idx = state.tasks.findIndex(x => x.id === editingId);
    if (idx >= 0) state.tasks[idx] = { ...state.tasks[idx], name, duration: dur, predecessors: ant, start, end,
      notes, color, percentComplete: pct, responsible: resp, taskType: typeVal };
    toast('✅ Tarefa atualizada');
  }
  closeModal();
  cascadeRecalc();
  render();
}

function deleteTask(id) {
  const t = state.tasks.find(x => x.id === id);
  if (t) { _deletedBuffer.push(t); if (_deletedBuffer.length > 5) _deletedBuffer.shift(); }
  state.tasks = state.tasks.filter(t => t.id !== id);
  if (selectedId === id) selectedId = null;
  toast('🗑 Tarefa removida (Ctrl+Z para desfazer)'); render();
}

// ── Export / Import JSON ──
function exportJSON() {
  const blob = new Blob([JSON.stringify(state, null, 2)], { type: 'application/json' });
  const url  = URL.createObjectURL(blob);
  const a    = Object.assign(document.createElement('a'), {
    href: url,
    download: `cronograma_${state.projectName.replace(/[^\w\sÀ-ÿ]/g,'').replace(/\s+/g,'_')}.json`
  });
  a.click(); URL.revokeObjectURL(url);
  toast('📥 JSON exportado');
}
function importJSON(file) {
  const r = new FileReader();
  r.onload = e => {
    try {
      const p = JSON.parse(e.target.result);
      if (!Array.isArray(p.tasks)) throw 0;
      state = { ...state, ...p };
      projectNameEl.value = state.projectName;
      selectedId = null;
      toast('✅ Projeto importado!'); render();
    } catch { toast('❌ Arquivo inválido'); }
  };
  r.readAsText(file);
}

// ── Splitter (mouse + touch) ──
(function() {
  const sp = $('#splitter'), tp = $('#table-panel');
  let drag = false, sx = 0, sw = 0;

  function startDrag(clientX) { drag=true; sx=clientX; sw=tp.offsetWidth; sp.classList.add('dragging'); document.body.style.userSelect='none'; document.body.style.cursor='col-resize'; }
  function moveDrag(clientX)  { if (!drag) return; tp.style.width = Math.max(200, Math.min(sw+clientX-sx, window.innerWidth*.80))+'px'; renderGantt(); }
  function endDrag()          { if (!drag) return; drag=false; sp.classList.remove('dragging'); document.body.style.userSelect=''; document.body.style.cursor=''; }

  // Mouse
  sp.addEventListener('mousedown', e => startDrag(e.clientX));
  document.addEventListener('mousemove', e => moveDrag(e.clientX));
  document.addEventListener('mouseup', endDrag);

  // Touch
  sp.addEventListener('touchstart', e => { e.preventDefault(); startDrag(e.touches[0].clientX); }, { passive: false });
  document.addEventListener('touchmove', e => { if (drag) { e.preventDefault(); moveDrag(e.touches[0].clientX); } }, { passive: false });
  document.addEventListener('touchend', endDrag);
})();

// ── Column Resize ──
(function() {
  // Indices das colunas redimensionáveis (skip 0=#, skip last=Ações)
  const RESIZABLE_COLS = [1, 2, 3, 4, 5]; // Nome, Dur, Início, Fim, Antec
  let colDrag = false, colTh = null, colSx = 0, colSw = 0;

  function injectResizers() {
    const ths = document.querySelectorAll('#task-table thead th');
    ths.forEach((th, i) => {
      if (!RESIZABLE_COLS.includes(i)) return;
      if (th.querySelector('.col-resizer')) return; // já injetado
      const div = document.createElement('div');
      div.className = 'col-resizer';
      th.appendChild(div);
    });
  }

  function startColDrag(th, clientX) {
    colDrag = true; colTh = th; colSx = clientX; colSw = th.offsetWidth;
    document.body.style.userSelect = 'none'; document.body.style.cursor = 'col-resize';
    th.querySelector('.col-resizer').classList.add('dragging');
  }
  function moveColDrag(clientX) {
    if (!colDrag || !colTh) return;
    const w = Math.max(40, colSw + clientX - colSx);
    colTh.style.width = w + 'px'; colTh.style.minWidth = w + 'px';
  }
  function endColDrag() {
    if (!colDrag) return; colDrag = false;
    if (colTh) { const r = colTh.querySelector('.col-resizer'); if (r) r.classList.remove('dragging'); }
    colTh = null; document.body.style.userSelect = ''; document.body.style.cursor = '';
  }

  document.addEventListener('mousemove', e => moveColDrag(e.clientX));
  document.addEventListener('mouseup', endColDrag);
  document.addEventListener('touchmove', e => { if (colDrag) { e.preventDefault(); moveColDrag(e.touches[0].clientX); } }, { passive: false });
  document.addEventListener('touchend', endColDrag);

  // Delegação de eventos no thead
  document.addEventListener('mousedown', e => {
    const resizer = e.target.closest('.col-resizer');
    if (!resizer) return;
    e.preventDefault();
    startColDrag(resizer.parentElement, e.clientX);
  });
  document.addEventListener('touchstart', e => {
    const resizer = e.target.closest('.col-resizer');
    if (!resizer) return;
    e.preventDefault();
    startColDrag(resizer.parentElement, e.touches[0].clientX);
  }, { passive: false });

  // Injetar após cada render
  const origRender = window.render;
  window.render = function() { origRender && origRender.apply(this, arguments); injectResizers(); };
  // Injetar agora se a tabela já existe
  injectResizers();
})();

