document.addEventListener('keydown', e => {
  if (e.key === 'Escape' && !modalOverlay.hidden) { closeModal(); return; }
  if (e.ctrlKey && e.key === 'z' && !['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)) {
    e.preventDefault();
    if (_deletedBuffer.length) {
      const task = _deletedBuffer.pop();
      state.tasks.push(task);
      toast('↩ Tarefa restaurada: ' + task.name); render();
    } else { toast('Nenhuma tarefa para restaurar'); }
    return;
  }
  if (e.ctrlKey && e.key === 'n' && !['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)) {
    e.preventDefault(); openModal(null);
  }
  if (e.key === 'F5' && !modalOverlay.hidden === false) {
    e.preventDefault(); cascadeRecalc(); render(); toast('🔄 Datas recalculadas');
  }
});

