// ── Sprint 5: Drag to reorder ──
(function() {
  let dragSrcId = null;
  taskBodyEl.addEventListener('dragstart', e => {
    const row = e.target.closest('tr[data-id]');
    if (!row) return;
    dragSrcId = parseInt(row.dataset.id);
    e.dataTransfer.effectAllowed = 'move';
  });
  taskBodyEl.addEventListener('dragover', e => {
    e.preventDefault();
    const row = e.target.closest('tr[data-id]');
    if (!row) return;
    document.querySelectorAll('tr.drag-over').forEach(r => r.classList.remove('drag-over'));
    row.classList.add('drag-over');
  });
  taskBodyEl.addEventListener('dragleave', e => {
    const row = e.target.closest('tr[data-id]');
    if (row) row.classList.remove('drag-over');
  });
  taskBodyEl.addEventListener('drop', e => {
    e.preventDefault();
    document.querySelectorAll('tr.drag-over').forEach(r => r.classList.remove('drag-over'));
    const row = e.target.closest('tr[data-id]');
    if (!row) return;
    const targetId = parseInt(row.dataset.id);
    if (dragSrcId === targetId) return;
    const srcIdx = state.tasks.findIndex(t => t.id === dragSrcId);
    const tgtIdx = state.tasks.findIndex(t => t.id === targetId);
    if (srcIdx < 0 || tgtIdx < 0) return;
    const [moved] = state.tasks.splice(srcIdx, 1);
    state.tasks.splice(tgtIdx, 0, moved);
    cascadeRecalc();
    render();
    toast('↕️ Ordem atualizada');
  });
})();

