// ── Exportar PDF — Cronograma limpo ──
function exportPDF() {
  const { jsPDF } = window.jspdf;
  const tasks = state.tasks;
  if (!tasks.length) { toast('⚠️ Nenhuma tarefa para exportar'); return; }

  const supervisor = state.supervisorName || document.getElementById('supervisor-name').value.trim() || '—';
  const projectName = state.projectName || 'Sem nome';
  const emitDate = new Date().toLocaleDateString('pt-BR', { day:'2-digit', month:'long', year:'numeric' });

  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const PW = 210, PH = 297, ML = 14, MR = 14;

  // ── Paleta ──
  const NAVY  = [30,41,59];
  const BLUE  = [37,99,235];
  const TEAL  = [16,185,129];
  const BLUE2 = [59,130,246];
  const SLATE = [100,116,139];
  const LTBG  = [248,250,252];
  const WHITE = [255,255,255];
  const DARK  = [15,23,42];
  const BORD  = [226,232,240];

  const fmtD = iso => {
    if (!iso) return '—';
    const d = new Date(iso);
    return `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`;
  };

  function drawFooter(pg, total) {
    doc.setPage(pg);
    doc.setDrawColor(...BORD); doc.setLineWidth(0.3);
    doc.line(ML, PH-13, PW-MR, PH-13);
    doc.setFontSize(6.5); doc.setFont('helvetica','normal'); doc.setTextColor(...SLATE);
    doc.text('Hagana Tecnologia — Segurança Eletrônica & Controle de Acesso', ML, PH-8);
    doc.text(`Página ${pg} de ${total}`, PW/2, PH-8, { align:'center' });
    doc.text('Documento gerado eletronicamente.', PW-MR, PH-8, { align:'right' });
  }

  // ────────────────────────────────
  // CABEÇALHO
  // ────────────────────────────────
  // Faixa azul-marinho
  doc.setFillColor(...NAVY);
  doc.rect(0, 0, PW, 50, 'F');
  // Linha accent
  doc.setFillColor(...BLUE);
  doc.rect(0, 50, PW, 2.5, 'F');

  // Logo
  try { doc.addImage(HAGANA_LOGO_B64, 'PNG', ML, 7, 20, 32); } catch(e) {}

  // Texto empresa
  doc.setFont('helvetica','bold'); doc.setFontSize(14);
  doc.setTextColor(248,250,252);
  doc.text('HAGANA TECNOLOGIA', ML+26, 18);

  doc.setFont('helvetica','normal'); doc.setFontSize(8);
  doc.setTextColor(148,163,184);
  doc.text('Segurança Eletrônica & Controle de Acesso', ML+26, 25);

  doc.setDrawColor(71,85,105); doc.setLineWidth(0.3);
  doc.line(ML+26, 28, PW-MR, 28);

  doc.setFont('helvetica','bold'); doc.setFontSize(11.5);
  doc.setTextColor(248,250,252);
  doc.text('CRONOGRAMA DE OBRA', ML+26, 37);

  // Data no canto direito
  doc.setFont('helvetica','normal'); doc.setFontSize(7.5);
  doc.setTextColor(100,116,139);
  doc.text(emitDate, PW-MR, 18, { align:'right' });

  let Y = 58;

  // ────────────────────────────────
  // BLOCO PROJETO / SUPERVISOR
  // ────────────────────────────────
  // Fundo
  doc.setFillColor(248,250,252);
  doc.roundedRect(ML, Y, PW-ML-MR, 26, 2, 2, 'F');
  doc.setDrawColor(...BORD); doc.setLineWidth(0.3);
  doc.roundedRect(ML, Y, PW-ML-MR, 26, 2, 2, 'S');

  // Barra esquerda azul
  doc.setFillColor(...BLUE);
  doc.roundedRect(ML, Y, 3, 26, 1, 1, 'F');

  const halfW = (PW-ML-MR)/2;

  // Coluna esquerda — Projeto
  doc.setFontSize(6.5); doc.setFont('helvetica','bold'); doc.setTextColor(...SLATE);
  doc.text('PROJETO', ML+7, Y+7);
  doc.setFontSize(11); doc.setFont('helvetica','bold'); doc.setTextColor(...DARK);
  const pn = projectName.length > 38 ? projectName.slice(0,37)+'…' : projectName;
  doc.text(pn, ML+7, Y+16);

  // Divisória vertical
  doc.setDrawColor(...BORD); doc.setLineWidth(0.3);
  doc.line(ML+halfW, Y+4, ML+halfW, Y+22);

  // Coluna direita — Supervisor
  doc.setFontSize(6.5); doc.setFont('helvetica','bold'); doc.setTextColor(...SLATE);
  doc.text('SUPERVISOR RESPONSÁVEL', ML+halfW+5, Y+7);
  doc.setFontSize(11); doc.setFont('helvetica','bold'); doc.setTextColor(...DARK);
  const sv = supervisor.length > 28 ? supervisor.slice(0,27)+'…' : supervisor;
  doc.text(sv, ML+halfW+5, Y+16);

  // Rodapé do bloco — período
  const allS = tasks.map(t=>t.start).filter(Boolean).map(x=>new Date(x).getTime());
  const allE = tasks.map(t=>t.end).filter(Boolean).map(x=>new Date(x).getTime());
  const pStart = allS.length ? fmtD(new Date(Math.min(...allS)).toISOString()) : '—';
  const pEnd   = allE.length ? fmtD(new Date(Math.max(...allE)).toISOString()) : '—';

  doc.setFontSize(7); doc.setFont('helvetica','normal'); doc.setTextColor(...SLATE);
  doc.text(`Período: ${pStart} → ${pEnd}`, ML+7, Y+23);

  const tot = tasks.reduce((a,t)=>a+(t.duration||0),0);
  doc.text(`${tasks.length} tarefa${tasks.length!==1?'s':''}  ·  ${tot} dias úteis`, ML+halfW+5, Y+23);

  Y += 32;

  // ────────────────────────────────
  // TABELA DE TAREFAS
  // ────────────────────────────────
  // Definir colunas (totalizando PW-ML-MR = 182mm)
  // #(8) | Nome(78) | Dur(16) | Início(26) | Fim(26) | Antec(14) | Resp(14)  = 182 ✓
  const C = {
    num:   ML,          // 8
    name:  ML+8,        // 78
    dur:   ML+86,       // 16
    ini:   ML+102,      // 26
    fim:   ML+128,      // 26
    ant:   ML+154,      // 14
    resp:  ML+168,      // 14 → alinha à direita em PW-MR
  };
  const ROW_H = 8;

  function drawTableHeader() {
    doc.setFillColor(...NAVY);
    doc.roundedRect(ML, Y, PW-ML-MR, 8, 1.5, 1.5, 'F');
    doc.setFontSize(6.5); doc.setFont('helvetica','bold'); doc.setTextColor(248,250,252);
    doc.text('#',         C.num+4,  Y+5.5, { align:'center' });
    doc.text('NOME DA TAREFA', C.name, Y+5.5);
    doc.text('DUR.',      C.dur+8,  Y+5.5, { align:'center' });
    doc.text('INÍCIO',    C.ini+13, Y+5.5, { align:'center' });
    doc.text('FIM',       C.fim+13, Y+5.5, { align:'center' });
    doc.text('ANTEC.',    C.ant,    Y+5.5);
    doc.text('RESPONSÁVEL', C.resp, Y+5.5);
    Y += 8;
  }

  drawTableHeader();

  tasks.forEach((t, i) => {
    if (Y + ROW_H > PH - 22) {
      doc.addPage();
      Y = 18;
      drawTableHeader();
    }

    if (i % 2 === 0) {
      doc.setFillColor(...LTBG);
      doc.rect(ML, Y, PW-ML-MR, ROW_H, 'F');
    }

    // Barra lateral colorida
    const pct = t.percentComplete || 0;
    const sideC = pct===100 ? TEAL : pct>0 ? BLUE2 : BLUE;
    doc.setFillColor(...sideC);
    doc.rect(ML, Y, 3, ROW_H, 'F');

    // Número
    doc.setFontSize(6.5); doc.setFont('helvetica','bold'); doc.setTextColor(...SLATE);
    doc.text(String(i+1), C.num+4, Y+5.5, { align:'center' });

    // Nome — largura segura 76mm
    doc.setFont('helvetica','normal'); doc.setTextColor(...DARK);
    const nmW = 76;
    const nmStr = doc.splitTextToSize(t.name, nmW)[0]; // só 1 linha
    doc.text(nmStr, C.name, Y+5.5);

    // Duração
    doc.setFont('helvetica','bold'); doc.setTextColor(...BLUE);
    doc.text((t.duration||0)+'d', C.dur+8, Y+5.5, { align:'center' });

    // Datas
    doc.setFont('helvetica','normal'); doc.setTextColor(...SLATE);
    doc.text(fmtD(t.start), C.ini+13, Y+5.5, { align:'center' });
    doc.text(fmtD(t.end),   C.fim+13, Y+5.5, { align:'center' });

    // Antecessoras
    doc.text(t.predecessors ? String(t.predecessors) : '—', C.ant, Y+5.5);

    // Responsável
    const resp = ((t.responsible||'')).slice(0,12) || '—';
    doc.text(resp, C.resp, Y+5.5);

    // Linha separadora
    doc.setDrawColor(...BORD); doc.setLineWidth(0.15);
    doc.line(ML+3, Y+ROW_H, PW-MR, Y+ROW_H);

    Y += ROW_H;
  });

  Y += 5;
  if (Y < PH - 28) {
    doc.setFontSize(6.5); doc.setFont('helvetica','italic'); doc.setTextColor(...SLATE);
    doc.text('* Duração em dias úteis — finais de semana e feriados nacionais não contabilizados.', ML, Y);
  }

  // Rodapés
  const total = doc.getNumberOfPages();
  for (let p = 1; p <= total; p++) drawFooter(p, total);

  const fname = `Cronograma_${projectName.replace(/[^\w\s]/g,'').replace(/\s+/g,'_')}_${new Date().toISOString().slice(0,10)}.pdf`;
  doc.save(fname);
  toast('📄 PDF exportado!');
}


$('#btn-export-pdf').addEventListener('click', exportPDF);

