//  RELATÓRIO SEMANAL — lógica completa
// ════════════════════════════════════════════════════════

// ── View toggle ──
let currentView = 'gantt'; // 'gantt' | 'table' | 'relatorio'

const mainEl        = $('#main');
const relPanel      = $('#relatorio-panel');
const tablePanel    = $('#table-panel');
const splitterEl    = $('#splitter');
const ganttPanel    = $('#gantt-panel');

function setView(v) {
  currentView = v;
  // Reset toolbar active
  $$('.btn-t').forEach(b => b.classList.remove('active'));

  if (v === 'relatorio') {
    mainEl.style.display = 'none';
    relPanel.style.display = 'block';
    $('#view-relatorio').classList.add('active');
    renderRelatorios();
  } else {
    mainEl.style.display = '';
    relPanel.style.display = 'none';
    if (v === 'gantt') {
      tablePanel.style.display = '';
      splitterEl.style.display = '';
      ganttPanel.style.display = '';
      $('#view-gantt').classList.add('active');
    } else {
      // table-only
      tablePanel.style.display = '';
      splitterEl.style.display = 'none';
      ganttPanel.style.display = 'none';
      $('#view-table').classList.add('active');
    }
  }
}

// Wire existing view buttons
$('#view-gantt').addEventListener('click', () => setView('gantt'));
$('#view-table').addEventListener('click', () => setView('table'));
$('#view-relatorio').addEventListener('click', () => setView('relatorio'));

// ── Helper: get Monday/Sunday of current week ──
function getMondayOfWeek(d) {
  const dt = new Date(d);
  const day = dt.getDay(); // 0=Sun
  const diff = (day === 0) ? -6 : 1 - day;
  dt.setDate(dt.getDate() + diff);
  dt.setHours(0,0,0,0);
  return dt;
}
function getSundayOfWeek(d) {
  const mon = getMondayOfWeek(d);
  const sun = new Date(mon);
  sun.setDate(mon.getDate() + 6);
  return sun;
}
function toDateInput(d) {
  return d.toISOString().slice(0,10);
}
function fmtDateBR(iso) {
  if (!iso) return '—';
  const [y,m,d] = iso.split('-');
  return `${d}/${m}/${y}`;
}

// ── Render relatório panel ──
function renderRelatorios() {
  const listEl = $('#rel-list');
  const emptyEl = $('#rel-empty');
  if (!state.relatorios || !state.relatorios.length) {
    listEl.innerHTML = '';
    emptyEl.style.display = '';
    return;
  }
  emptyEl.style.display = 'none';

  // Sort newest first
  const sorted = [...state.relatorios].sort((a,b) => b.weekStart.localeCompare(a.weekStart));
  listEl.innerHTML = sorted.map(rel => {
    const checkedCount = Object.values(rel.taskChecks||{}).filter(Boolean).length;
    const totalTasks = state.tasks.length;
    const pct = totalTasks ? Math.round(checkedCount/totalTasks*100) : 0;
    const tasksHtml = state.tasks.map(t => {
      const checked = rel.taskChecks && rel.taskChecks[t.id] ? 'checked' : '';
      const pctTask = t.percentComplete || 0;
      const statusColor = pctTask>=100 ? '#10b981' : pctTask>0 ? '#3b82f6' : '#94a3b8';
      return `<label class="rel-task-item" style="display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:6px;cursor:pointer;transition:background 0.15s;">
        <input type="checkbox" data-relid="${rel.id}" data-taskid="${t.id}" ${checked} style="width:16px;height:16px;accent-color:#2563eb;cursor:pointer;">
        <span style="flex:1;font-size:13px;color:var(--text);">${t.name}</span>
        <span style="font-size:11px;color:${statusColor};font-weight:600;white-space:nowrap;">${pctTask}% concluído</span>
      </label>`;
    }).join('');

    return `<div class="rel-card" data-relid="${rel.id}" style="background:var(--surface);border:1px solid var(--border);border-radius:10px;margin-bottom:16px;overflow:hidden;">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px;background:var(--header-bg);color:var(--header-text);gap:12px;flex-wrap:wrap;">
        <div>
          <span style="font-size:13px;font-weight:700;">📅 Semana: ${fmtDateBR(rel.weekStart)} — ${fmtDateBR(rel.weekEnd)}</span>
        </div>
        <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
          <span style="font-size:12px;background:rgba(255,255,255,0.15);padding:3px 10px;border-radius:20px;">${checkedCount} / ${totalTasks} tarefas concluídas esta semana</span>
          <button class="btn btn-primary" data-pdf-rel="${rel.id}" style="font-size:12px;padding:5px 12px;" title="Resumo de uma página para enviar ao cliente">📄 Exportar PDF</button>
          <button class="btn btn-ghost" data-pdf-full="${rel.id}" style="font-size:12px;padding:5px 12px;" title="Relatório detalhado com indicadores, curva S e tabela de atividades">📊 Completo</button>
          <button class="btn btn-danger" data-del-rel="${rel.id}" style="font-size:12px;padding:5px 10px;background:var(--danger);border:none;color:#fff;border-radius:6px;cursor:pointer;">🗑</button>
        </div>
      </div>
      <div style="padding:14px 18px;">
        <div style="margin-bottom:10px;">
          <div style="display:flex;justify-content:space-between;margin-bottom:6px;">
            <span style="font-size:12px;color:var(--text-2);font-weight:600;">PROGRESSO DA SEMANA</span>
            <span style="font-size:12px;font-weight:700;color:var(--accent);">${pct}%</span>
          </div>
          <div style="background:var(--border);border-radius:20px;height:8px;overflow:hidden;">
            <div style="background:var(--accent);width:${pct}%;height:100%;border-radius:20px;transition:width 0.4s;"></div>
          </div>
        </div>
        <div style="margin-bottom:14px;max-height:280px;overflow-y:auto;">
          <p style="font-size:11.5px;color:var(--text-2);margin-bottom:6px;font-weight:600;">TAREFAS REALIZADAS NESTA SEMANA:</p>
          <div style="display:flex;flex-direction:column;gap:2px;">${tasksHtml}</div>
        </div>
        <div>
          <label style="font-size:11.5px;color:var(--text-2);font-weight:600;display:block;margin-bottom:5px;">OBSERVAÇÕES / OCORRÊNCIAS:</label>
          <textarea data-obs-rel="${rel.id}" rows="3" placeholder="Ex: Chuva forte impediu serviços externos na quinta-feira..." style="width:100%;padding:8px 10px;border:1px solid var(--border-2);border-radius:6px;background:var(--surface);color:var(--text);font-family:inherit;font-size:13px;resize:vertical;outline:none;">${rel.observations||''}</textarea>
        </div>
        <div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap;align-items:center;">
          <label style="font-size:12px;color:var(--text-2);">Semana:</label>
          <input type="date" data-ws-rel="${rel.id}" value="${rel.weekStart}" style="font-size:12px;padding:4px 8px;border:1px solid var(--border-2);border-radius:5px;background:var(--surface);color:var(--text);">
          <span style="color:var(--text-3);">→</span>
          <input type="date" data-we-rel="${rel.id}" value="${rel.weekEnd}" style="font-size:12px;padding:4px 8px;border:1px solid var(--border-2);border-radius:5px;background:var(--surface);color:var(--text);">
          <button class="btn btn-primary" data-save-rel="${rel.id}" style="font-size:12px;padding:5px 12px;">💾 Salvar</button>
        </div>
      </div>
    </div>`;
  }).join('');

  // Wire checkboxes
  listEl.querySelectorAll('input[type=checkbox][data-relid]').forEach(cb => {
    cb.addEventListener('change', () => {
      const rel = state.relatorios.find(r => r.id == cb.dataset.relid);
      if (!rel) return;
      if (!rel.taskChecks) rel.taskChecks = {};
      rel.taskChecks[cb.dataset.taskid] = cb.checked;
      save();
      // Update progress bar inline
      const card = cb.closest('.rel-card');
      if (card) {
        const checks = Object.values(rel.taskChecks).filter(Boolean).length;
        const tot = state.tasks.length;
        const p = tot ? Math.round(checks/tot*100) : 0;
        const bar = card.querySelector('[style*="background:var(--accent)"]');
        if (bar) bar.style.width = p + '%';
        const pctLabel = card.querySelector('[style*="color:var(--accent)"]');
        if (pctLabel && pctLabel.tagName === 'SPAN') pctLabel.textContent = p + '%';
        const countBadge = card.querySelector('[style*="rgba(255,255,255,0.15)"]');
        if (countBadge) countBadge.textContent = `${checks} / ${tot} tarefas concluídas esta semana`;
      }
    });
  });

  // Wire observations save
  listEl.querySelectorAll('textarea[data-obs-rel]').forEach(ta => {
    ta.addEventListener('input', () => {
      const rel = state.relatorios.find(r => r.id == ta.dataset.obsRel);
      if (rel) { rel.observations = ta.value; save(); }
    });
  });

  // Wire date inputs
  listEl.querySelectorAll('input[data-ws-rel]').forEach(inp => {
    inp.addEventListener('change', () => {
      const rel = state.relatorios.find(r => r.id == inp.dataset.wsRel);
      if (rel) { rel.weekStart = inp.value; save(); }
    });
  });
  listEl.querySelectorAll('input[data-we-rel]').forEach(inp => {
    inp.addEventListener('change', () => {
      const rel = state.relatorios.find(r => r.id == inp.dataset.weRel);
      if (rel) { rel.weekEnd = inp.value; save(); }
    });
  });

  // Wire save buttons
  listEl.querySelectorAll('[data-save-rel]').forEach(btn => {
    btn.addEventListener('click', () => {
      save(); toast('💾 Relatório salvo!');
    });
  });

  // Wire delete buttons
  listEl.querySelectorAll('[data-del-rel]').forEach(btn => {
    btn.addEventListener('click', () => {
      if (!confirm('Excluir este relatório?')) return;
      state.relatorios = state.relatorios.filter(r => r.id != btn.dataset.delRel);
      save(); renderRelatorios();
      toast('🗑 Relatório excluído.');
    });
  });

  // Wire PDF export buttons
  listEl.querySelectorAll('[data-pdf-rel]').forEach(btn => {
    btn.addEventListener('click', () => {
      const rel = state.relatorios.find(r => r.id == btn.dataset.pdfRel);
      if (rel) exportRelatorioClientePDF(rel);
    });
  });
  listEl.querySelectorAll('[data-pdf-full]').forEach(btn => {
    btn.addEventListener('click', () => {
      const rel = state.relatorios.find(r => r.id == btn.dataset.pdfFull);
      if (rel) exportRelatorioPDF(rel);
    });
  });
}

// ── Nova semana ──
$('#btn-rel-new').addEventListener('click', () => {
  const today = new Date();
  const mon = getMondayOfWeek(today);
  const sun = getSundayOfWeek(today);
  const id = state.relNextId++;
  if (!state.relatorios) state.relatorios = [];
  state.relatorios.push({
    id, weekStart: toDateInput(mon), weekEnd: toDateInput(sun),
    observations: '', taskChecks: {}
  });
  save(); renderRelatorios();
  toast('📅 Nova semana adicionada!');
});

// ── Export Relatório PDF (painel executivo navegável) ──
function exportRelatorioPDF(rel) {
  if (!window.jspdf || !window.jspdf.jsPDF) {
    toast('Biblioteca de PDF não carregou. Verifique a conexão com a internet.', 3500);
    return;
  }
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ orientation: 'l', unit: 'mm', format: 'a4' });

  // ── Página / grade ──
  const PW = 297, PH = 210, ML = 12, MR = 12, CW = PW - ML - MR;
  const TOP = 27, BOTTOM = PH - 12;

  // ── Paleta (identidade Hagana) ──
  const C = {
    navy:   [39, 40, 103],
    navy2:  [72, 76, 160],
    tint:   [205, 207, 232],
    ink:    [28, 30, 44],
    gray:   [96, 100, 116],
    gray2:  [148, 152, 166],
    line:   [220, 222, 230],
    bg:     [244, 245, 248],
    white:  [255, 255, 255],
    yellow: [253, 234, 0],
    green:  [22, 135, 72],
    amber:  [205, 132, 0],
    red:    [192, 44, 44],
  };
  const fill = c => doc.setFillColor(c[0], c[1], c[2]);
  const stroke = c => doc.setDrawColor(c[0], c[1], c[2]);
  const color = c => doc.setTextColor(c[0], c[1], c[2]);
  const font = (style, size) => { doc.setFont('helvetica', style); doc.setFontSize(size); };

  // ── Datas ──
  const dayOf = iso => { if (!iso) return null; const d = new Date(iso); d.setHours(0,0,0,0); return d; };
  const parseYMD = s => { const [y,m,d] = s.split('-').map(Number); return new Date(y, m-1, d); };
  const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x; };
  const br = d => d ? d.toLocaleDateString('pt-BR', { day:'2-digit', month:'2-digit', year:'numeric' }) : '-';
  const brShort = d => d ? d.toLocaleDateString('pt-BR', { day:'2-digit', month:'2-digit' }) : '-';
  const MESES = ['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'];

  const tasks = state.tasks.slice();
  const starts = tasks.map(t => dayOf(t.start)).filter(Boolean);
  const ends   = tasks.map(t => dayOf(t.end)).filter(Boolean);
  const projStart = starts.length ? new Date(Math.min(...starts)) : parseYMD(rel.weekStart);
  const projEnd   = ends.length   ? new Date(Math.max(...ends))   : parseYMD(rel.weekEnd);
  const weekStart = parseYMD(rel.weekStart);
  const cutDate   = parseYMD(rel.weekEnd); // data de corte = fim do período

  const years = [];
  for (let y = projStart.getFullYear() - 1; y <= projEnd.getFullYear() + 1; y++) years.push(y);
  const HOL = buildHolidaySet(years);
  const isWork = d => !isWeekend(d) && !HOL.has(dateKey(new Date(d.getFullYear(), d.getMonth(), d.getDate(), 12)));
  const workdays = (a, b) => { // inclusivo
    if (!a || !b || b < a) return 0;
    let n = 0; const d = new Date(a);
    while (d <= b) { if (isWork(d)) n++; d.setDate(d.getDate() + 1); }
    return n;
  };

  // ── Histórico: fotografia do % real por relatório ──
  const rels = [...state.relatorios].sort((a,b) => a.weekStart.localeCompare(b.weekStart));
  const relIdx = rels.findIndex(r => r.id === rel.id);
  const isLatest = relIdx === rels.length - 1;
  if (isLatest || !rel.snapshot) {
    rel.snapshot = { takenAt: new Date().toISOString(), pct: {} };
    tasks.forEach(t => { rel.snapshot.pct[t.id] = t.percentComplete || 0; });
    save();
  }
  const reportNo = String(relIdx + 1).padStart(2, '0');
  const realOf = (t, r = rel) => {
    const v = r.snapshot && r.snapshot.pct ? r.snapshot.pct[t.id] : undefined;
    return v === undefined ? (t.percentComplete || 0) : v;
  };

  // ── Métricas ──
  const isFase = t => t.taskType === 'fase';
  const isMarco = t => t.taskType === 'marco';
  const weightOf = t => isFase(t) ? 0 : (isMarco(t) ? 0 : Math.max(Number(t.duration) || 0, 1));
  let totalW = tasks.reduce((s, t) => s + weightOf(t), 0);
  const W = t => totalW ? weightOf(t) : 1;
  if (!totalW) totalW = tasks.length || 1;

  const plannedAt = (t, ref) => {
    const s = dayOf(t.start), e = dayOf(t.end);
    if (!s || !e) return 0;
    if (ref < s) return 0;
    if (ref >= e) return 100;
    const tot = workdays(s, e);
    return tot ? Math.min(100, workdays(s, ref) / tot * 100) : 0;
  };
  const weighted = fn => tasks.reduce((s, t) => s + W(t) * fn(t), 0) / totalW;

  const realPct = weighted(t => realOf(t));
  const planPct = weighted(t => plannedAt(t, cutDate));
  const devPct  = realPct - planPct;
  const idp     = planPct > 0 ? realPct / planPct : null;
  const prevRel = relIdx > 0 ? rels[relIdx - 1] : null;
  const prevReal = prevRel && prevRel.snapshot ? weighted(t => realOf(t, prevRel)) : null;
  const weekGain = prevReal === null ? null : realPct - prevReal;
  const remainingWD = cutDate < projEnd ? workdays(addDays(cutDate, 1), projEnd) : 0;

  const STATUS = {
    done:   { label: 'Concluída',    c: C.green },
    late:   { label: 'Atrasada',     c: C.red },
    warn:   { label: 'Atenção',      c: C.amber },
    prog:   { label: 'Em andamento', c: C.navy2 },
    todo:   { label: 'A iniciar',    c: C.gray2 },
  };
  const rows = tasks.map((t, i) => {
    const re = realOf(t), pr = plannedAt(t, cutDate), gap = pr - re;
    let st;
    if (re >= 100) st = 'done';
    else if (gap >= 10) st = 'late';
    else if (gap >= 5) st = 'warn';
    else if (re > 0 || pr > 0) st = 'prog';
    else st = 'todo';
    return { t, n: i + 1, re, pr, dev: re - pr, st, s: dayOf(t.start), e: dayOf(t.end),
             checked: !!(rel.taskChecks && rel.taskChecks[t.id]) };
  });
  const countBy = k => rows.filter(r => !isFase(r.t) && r.st === k).length;
  const counts = { done: countBy('done'), prog: countBy('prog'), warn: countBy('warn'), late: countBy('late'), todo: countBy('todo') };
  const nActs = rows.filter(r => !isFase(r.t)).length;

  const overlaps = (r, a, b) => r.s && r.e && r.s <= b && r.e >= a;
  const plannedWeek = rows.filter(r => !isFase(r.t) && overlaps(r, weekStart, cutDate));
  const executedWeek = rows.filter(r => r.checked);
  const adherenceHits = plannedWeek.filter(r => r.checked).length;
  const adherence = plannedWeek.length ? adherenceHits / plannedWeek.length * 100 : null;
  const nextA = addDays(cutDate, 1), nextB = addDays(cutDate, 7);
  const nextWeek = rows.filter(r => !isFase(r.t) && r.re < 100 && (overlaps(r, nextA, nextB) || (r.e && r.e < nextA)));
  const pendLinks = []; // áreas clicáveis na visão geral -> [x,y,w,h,secao]

  // ── Utilitários de desenho ──
  const pct0 = v => Math.round(v) + '%';
  const pct1 = v => v.toFixed(1).replace('.', ',') + '%';
  const pp = v => (v > 0 ? '+' : v < 0 ? '-' : '') + Math.abs(v).toFixed(1).replace('.', ',') + ' p.p.';
  const fit = (txt, w) => {
    txt = String(txt || '');
    if (doc.getTextWidth(txt) <= w) return txt;
    while (txt.length > 1 && doc.getTextWidth(txt + '...') > w) txt = txt.slice(0, -1);
    return txt.trimEnd() + '...';
  };
  const hline = (x1, y, x2, c = C.line, w = 0.2) => { stroke(c); doc.setLineWidth(w); doc.line(x1, y, x2, y); };
  const panel = (x, y, w, h, title, sub) => {
    fill(C.white); stroke(C.line); doc.setLineWidth(0.2); doc.rect(x, y, w, h, 'FD');
    if (title) {
      font('bold', 7.6); color(C.ink); doc.text(title, x + 4, y + 6);
      if (sub) { font('normal', 6.2); color(C.gray2); doc.text(sub, x + 4, y + 9.6); }
    }
  };
  const ringSeg = (cx, cy, r0, r1, a0, a1, c) => {
    if (a1 - a0 <= 0.01) return;
    const pts = [], steps = Math.max(2, Math.ceil((a1 - a0) / 4));
    for (let i = 0; i <= steps; i++) { const a = (a0 + (a1 - a0) * i / steps) * Math.PI / 180; pts.push([cx + r1 * Math.sin(a), cy - r1 * Math.cos(a)]); }
    for (let i = steps; i >= 0; i--) { const a = (a0 + (a1 - a0) * i / steps) * Math.PI / 180; pts.push([cx + r0 * Math.sin(a), cy - r0 * Math.cos(a)]); }
    const deltas = pts.slice(1).map((p, i) => [p[0] - pts[i][0], p[1] - pts[i][1]]);
    fill(c); doc.lines(deltas, pts[0][0], pts[0][1], [1, 1], 'F', true);
  };
  const pill = (x, y, st, w = 21) => {
    const s = STATUS[st];
    fill(s.c); doc.roundedRect(x, y - 2.9, w, 4, 0.8, 0.8, 'F');
    font('bold', 5.9); color(C.white); doc.text(s.label.toUpperCase(), x + w / 2, y - 0.1, { align: 'center' });
  };
  const alpha = (a, fn) => { try { doc.setGState(new doc.GState({ opacity: a })); fn(); doc.setGState(new doc.GState({ opacity: 1 })); } catch (e) { fn(); } };

  const sections = {}; // chave -> página inicial
  const pageSection = {}; // página -> chave
  const newPage = key => {
    if (Object.keys(pageSection).length) doc.addPage();
    const p = doc.getNumberOfPages();
    if (!(key in sections)) sections[key] = p;
    pageSection[p] = key;
    fill(C.bg); doc.rect(0, 0, PW, PH, 'F');
    return p;
  };

  // ════════════════════════════════════════════════
  // 1. VISÃO GERAL
  // ════════════════════════════════════════════════
  newPage('overview');
  let y = TOP;

  // KPIs
  const kpis = [
    { label: 'AVANÇO FÍSICO REAL', val: pct1(realPct), sub: 'Ponderado pela duração', bar: C.navy },
    { label: 'AVANÇO PREVISTO', val: pct1(planPct), sub: 'Planejado até ' + brShort(cutDate), bar: C.navy2 },
    { label: 'DESVIO', val: pp(devPct), sub: devPct >= -2 ? 'Dentro do planejado' : devPct >= -8 ? 'Requer atenção' : 'Abaixo do planejado',
      bar: devPct >= -2 ? C.green : devPct >= -8 ? C.amber : C.red, valC: devPct >= -2 ? C.green : devPct >= -8 ? C.amber : C.red },
    { label: 'ÍNDICE DE DESEMPENHO', val: idp === null ? '-' : idp.toFixed(2).replace('.', ','), sub: 'Real / previsto (meta 1,00)',
      bar: idp === null || idp >= 0.95 ? C.green : idp >= 0.85 ? C.amber : C.red },
    { label: 'AVANÇO NA SEMANA', val: weekGain === null ? '-' : pp(weekGain), sub: weekGain === null ? 'Primeiro relatório da série' : 'Em relação ao relatório ' + String(relIdx).padStart(2, '0'), bar: C.navy2 },
    { label: 'TÉRMINO PROGRAMADO', val: br(projEnd), sub: remainingWD + ' dias úteis restantes', bar: C.ink, small: true },
  ];
  const kGap = 3, kW = (CW - kGap * (kpis.length - 1)) / kpis.length, kH = 23;
  kpis.forEach((k, i) => {
    const x = ML + i * (kW + kGap);
    panel(x, y, kW, kH);
    fill(k.bar); doc.rect(x, y, kW, 0.9, 'F');
    font('bold', 6); color(C.gray); doc.text(k.label, x + 4, y + 6.5, { charSpace: 0.15 });
    font('bold', k.small ? 14 : 17); color(k.valC || C.ink); doc.text(k.val, x + 4, y + 15.5);
    font('normal', 6.2); color(C.gray2); doc.text(fit(k.sub, kW - 8), x + 4, y + 20);
  });
  y += kH + 4;

  // Curva S
  const sW = 178, sH = 78;
  panel(ML, y, sW, sH, 'Curva S  -  avanço físico acumulado', 'Previsto conforme cronograma x real apurado nos relatórios semanais');
  (() => {
    const gx = ML + 14, gy = y + 16, gw = sW - 22, gh = sH - 28;
    const t0 = getMondayOfWeek(projStart), t1 = addDays(getSundayOfWeek(projEnd), 0);
    const span = Math.max(1, t1 - t0);
    const X = d => gx + (d - t0) / span * gw;
    const Y = v => gy + gh - v / 100 * gh;
    // grade
    font('normal', 5.8); color(C.gray2);
    [0, 25, 50, 75, 100].forEach(v => {
      hline(gx, Y(v), gx + gw, v === 0 ? C.gray2 : C.line, v === 0 ? 0.3 : 0.15);
      doc.text(v + '%', gx - 2, Y(v) + 1, { align: 'right' });
    });
    // pontos previstos semanais
    const planPts = [];
    for (let d = new Date(t0); d <= t1; d = addDays(d, 7)) planPts.push([d, weighted(t => plannedAt(t, addDays(d, 6)))]);
    planPts.unshift([new Date(t0), 0]);
    // rótulos do eixo X
    let lastX = -99;
    planPts.forEach(([d]) => { const x = X(d); if (x - lastX >= 12 && x <= gx + gw) { doc.text(brShort(d), x, gy + gh + 4, { align: 'center' }); lastX = x; } });
    // semana do relatório
    alpha(0.35, () => { fill(C.yellow); doc.rect(X(weekStart), gy, Math.max(0.8, X(addDays(cutDate, 1)) - X(weekStart)), gh, 'F'); });
    // área + linha prevista
    const ptsXY = planPts.map(([d, v]) => [X(addDays(d, 6)), Y(v)]); ptsXY[0] = [X(t0), Y(0)];
    alpha(0.10, () => {
      const poly = [...ptsXY, [ptsXY[ptsXY.length - 1][0], Y(0)], [ptsXY[0][0], Y(0)]];
      fill(C.navy2); doc.lines(poly.slice(1).map((p, i) => [p[0] - poly[i][0], p[1] - poly[i][1]]), poly[0][0], poly[0][1], [1, 1], 'F', true);
    });
    stroke(C.navy2); doc.setLineWidth(0.5);
    for (let i = 1; i < ptsXY.length; i++) doc.line(ptsXY[i - 1][0], ptsXY[i - 1][1], ptsXY[i][0], ptsXY[i][1]);
    // linha real (histórico de relatórios)
    const realPts = [[X(projStart), Y(0)]];
    rels.slice(0, relIdx + 1).forEach(r => {
      if (!r.snapshot && r !== rel) return;
      const d = parseYMD(r.weekEnd); if (d < projStart) return;
      realPts.push([X(d), Y(weighted(t => realOf(t, r)))]);
    });
    stroke(C.green); doc.setLineWidth(0.8);
    for (let i = 1; i < realPts.length; i++) doc.line(realPts[i - 1][0], realPts[i - 1][1], realPts[i][0], realPts[i][1]);
    realPts.slice(1).forEach(p => { fill(C.white); stroke(C.green); doc.setLineWidth(0.5); doc.circle(p[0], p[1], 0.9, 'FD'); });
    // corte
    const cx = X(cutDate);
    stroke(C.ink); doc.setLineWidth(0.25); doc.setLineDashPattern([0.8, 0.8], 0); doc.line(cx, gy - 1, cx, gy + gh); doc.setLineDashPattern([], 0);
    const last = realPts[realPts.length - 1];
    font('bold', 6.4); color(C.green); doc.text('Real ' + pct1(realPct), last[0] + 2, last[1] + (last[1] > Y(planPct) ? 3 : -1.5));
    color(C.navy2); doc.text('Prev. ' + pct1(planPct), cx + 2, Y(planPct) + (last[1] > Y(planPct) ? -1.5 : 3));
    font('normal', 5.8); color(C.gray); doc.text('corte ' + brShort(cutDate), cx, gy - 2, { align: 'center' });
    // legenda
    const lx = ML + sW - 64, ly = y + 6;
    stroke(C.navy2); doc.setLineWidth(0.6); doc.line(lx, ly - 1, lx + 6, ly - 1);
    font('normal', 6.2); color(C.gray); doc.text('Previsto', lx + 7.5, ly);
    stroke(C.green); doc.setLineWidth(0.8); doc.line(lx + 20, ly - 1, lx + 26, ly - 1);
    doc.text('Real', lx + 27.5, ly);
    alpha(0.5, () => { fill(C.yellow); doc.rect(lx + 36, ly - 2.6, 4, 3, 'F'); });
    doc.text('Semana', lx + 41.5, ly);
  })();

  // Distribuição por status (rosca)
  const dX = ML + sW + 4, dW = CW - sW - 4;
  panel(dX, y, dW, sH, 'Situação das atividades', 'Na data de corte, ' + br(cutDate));
  (() => {
    const cx = dX + 26, cy = y + 44, r1 = 17, r0 = 11.5;
    const order = ['done', 'prog', 'warn', 'late', 'todo'];
    let a = 0;
    const tot = nActs || 1;
    if (!nActs) ringSeg(cx, cy, r0, r1, 0, 359.9, C.line);
    order.forEach(k => { const sweep = counts[k] / tot * 360; if (sweep > 0) { ringSeg(cx, cy, r0, r1, a, a + sweep - (sweep < 359 ? 0.8 : 0), STATUS[k].c); a += sweep; } });
    font('bold', 15); color(C.ink); doc.text(String(nActs), cx, cy + 1.5, { align: 'center' });
    font('normal', 5.8); color(C.gray); doc.text('atividades', cx, cy + 5, { align: 'center' });
    let ly = y + 26;
    const lx = dX + 50;
    order.forEach(k => {
      fill(STATUS[k].c); doc.rect(lx, ly - 2.4, 2.8, 2.8, 'F');
      font('normal', 6.8); color(C.ink); doc.text(STATUS[k].label, lx + 4.5, ly);
      font('bold', 6.8); doc.text(String(counts[k]), dX + dW - 5, ly, { align: 'right' });
      font('normal', 5.8); color(C.gray2); doc.text(pct0(counts[k] / tot * 100), dX + dW - 12, ly, { align: 'right' });
      hline(lx, ly + 2.2, dX + dW - 5, C.line, 0.15);
      ly += 7;
    });
    font('normal', 5.6); color(C.gray2);
    doc.text(doc.splitTextToSize('Atraso: desvio >= 10 p.p. em relação ao previsto. Atenção: entre 5 e 10 p.p.', dW - 10), dX + 5, y + sH - 6);
  })();
  y += sH + 4;

  // Real x previsto por atividade
  const bH = BOTTOM - y, bW = 178;
  let bullets = rows.filter(r => !isFase(r.t));
  const maxB = Math.floor((bH - 16) / 5.2);
  let bSub = 'Barra = real  |  marcador = previsto na data de corte';
  if (bullets.length > maxB) { bullets = bullets.slice().sort((a, b) => a.dev - b.dev).slice(0, maxB); bSub = 'Maiores desvios (' + maxB + ' de ' + nActs + ')  |  barra = real, marcador = previsto'; }
  panel(ML, y, bW, bH, 'Real x previsto por atividade', bSub);
  (() => {
    const lx = ML + 4, labW = 66, gx = lx + labW + 2, gw = bW - labW - 30;
    let ry = y + 15;
    bullets.forEach(r => {
      font('normal', 6.4); color(C.ink); doc.text(fit(r.n + '. ' + r.t.name, labW), lx, ry + 1.8);
      fill(C.bg); doc.rect(gx, ry - 0.6, gw, 3.2, 'F');
      fill(STATUS[r.st].c); doc.rect(gx, ry - 0.6, gw * Math.min(100, r.re) / 100, 3.2, 'F');
      fill(C.ink); doc.rect(gx + gw * r.pr / 100 - 0.3, ry - 1.5, 0.6, 5, 'F');
      font('bold', 6.2); color(C.ink); doc.text(pct0(r.re), gx + gw + 3, ry + 1.8);
      font('normal', 5.8); color(r.dev < -5 ? C.red : C.gray2);
      doc.text(r.dev === 0 ? '0' : (r.dev > 0 ? '+' : '') + Math.round(r.dev), gx + gw + 23, ry + 1.8, { align: 'right' });
      pendLinks.push([ML, ry - 2, bW, 5.2, 'table']);
      ry += 5.2;
    });
    font('normal', 5.6); color(C.gray2); doc.text('real', gx + gw + 3, y + 12.6); doc.text('desv.', gx + gw + 23, y + 12.6, { align: 'right' });
  })();

  // Resumo + pontos de atenção
  const rX = ML + bW + 4, rW = CW - bW - 4;
  panel(rX, y, rW, bH, 'Resumo do período', br(weekStart) + ' a ' + br(cutDate));
  (() => {
    let ry = y + 17;
    const line = (label, val, c = C.ink) => {
      font('normal', 6.6); color(C.gray); doc.text(label, rX + 5, ry);
      font('bold', 6.8); color(c); doc.text(val, rX + rW - 5, ry, { align: 'right' });
      hline(rX + 5, ry + 2, rX + rW - 5, C.line, 0.15); ry += 6;
    };
    line('Atividades programadas na semana', String(plannedWeek.length));
    line('Atividades executadas na semana', String(executedWeek.length));
    line('Aderência à programação', adherence === null ? '-' : pct0(adherence), adherence === null ? C.ink : adherence >= 80 ? C.green : adherence >= 60 ? C.amber : C.red);
    line('Atividades concluídas (acumulado)', counts.done + ' de ' + nActs);
    ry += 2;
    font('bold', 6.4); color(C.ink); doc.text('PONTOS DE ATENÇÃO', rX + 5, ry, { charSpace: 0.15 }); ry += 4.5;
    const crit = rows.filter(r => !isFase(r.t) && (r.st === 'late' || r.st === 'warn')).sort((a, b) => a.dev - b.dev);
    if (!crit.length) {
      font('normal', 6.4); color(C.gray);
      doc.text(doc.splitTextToSize('Nenhuma atividade com desvio relevante na data de corte.', rW - 10), rX + 5, ry);
    } else {
      const room = Math.floor((y + bH - 4 - ry) / 5);
      crit.slice(0, room).forEach((r, i) => {
        fill(STATUS[r.st].c); doc.rect(rX + 5, ry - 2.3, 1, 3, 'F');
        font('normal', 6.3); color(C.ink); doc.text(fit(r.n + '. ' + r.t.name, rW - 30), rX + 8, ry);
        font('bold', 6.3); color(STATUS[r.st].c); doc.text(Math.round(r.dev) + ' p.p.', rX + rW - 5, ry, { align: 'right' });
        pendLinks.push([rX, ry - 3.5, rW, 5, 'table']);
        ry += 5;
        if (i === room - 1 && crit.length > room) { font('normal', 5.8); color(C.gray2); doc.text('+ ' + (crit.length - room) + ' outras na aba Atividades', rX + 8, ry); }
      });
    }
  })();

  // ════════════════════════════════════════════════
  // 2. CRONOGRAMA (Gantt)
  // ════════════════════════════════════════════════
  (() => {
    const headH = 11;
    const RH = Math.min(9, Math.max(6.2, (BOTTOM - TOP - headH - 12) / Math.max(1, rows.length)));
    const cols = [{ k: '#', w: 7 }, { k: 'Atividade', w: 76 }, { k: 'Início', w: 15 }, { k: 'Término', w: 15 }, { k: 'Real', w: 11 }];
    const leftW = cols.reduce((s, c) => s + c.w, 0);
    const gx = ML + leftW, gw = CW - leftW;
    const t0 = getMondayOfWeek(projStart), t1 = addDays(getSundayOfWeek(projEnd), 1);
    const span = t1 - t0;
    const X = d => gx + (d - t0) / span * gw;
    const perPage = Math.floor((BOTTOM - TOP - headH - 12) / RH);
    for (let p = 0; p < Math.max(1, Math.ceil(rows.length / perPage)); p++) {
      newPage('gantt');
      const chunk = rows.slice(p * perPage, (p + 1) * perPage);
      const tableH = headH + chunk.length * RH;
      panel(ML, TOP, CW, tableH + 12);
      const y0 = TOP + 3;
      // cabeçalho
      fill(C.navy); doc.rect(ML, TOP, CW, headH, 'F');
      font('bold', 6.3); color(C.white);
      let cx = ML;
      cols.forEach(c => { doc.text(c.k.toUpperCase(), c.k === '#' ? cx + c.w / 2 : cx + 2, TOP + headH - 3, c.k === '#' ? { align: 'center' } : {}); cx += c.w; });
      // meses e semanas
      font('bold', 6); color(C.white);
      for (let d = new Date(t0.getFullYear(), t0.getMonth(), 1); d < t1; d = new Date(d.getFullYear(), d.getMonth() + 1, 1)) {
        const a = Math.max(gx, X(d)), b = Math.min(gx + gw, X(new Date(d.getFullYear(), d.getMonth() + 1, 1)));
        if (b - a > 8) doc.text(MESES[d.getMonth()].toUpperCase() + '/' + String(d.getFullYear()).slice(2), (a + b) / 2, TOP + 4.2, { align: 'center' });
        stroke([90, 92, 150]); doc.setLineWidth(0.2); if (X(d) > gx) doc.line(X(d), TOP, X(d), TOP + headH);
      }
      font('normal', 5.2); doc.setTextColor(200, 202, 230);
      let lastX = -99;
      const bodyTop = TOP + headH, bodyBot = bodyTop + chunk.length * RH;
      for (let d = new Date(t0); d < t1; d = addDays(d, 7)) {
        const x = X(d);
        if (x - lastX >= 7.5 && x - gx > 1) { doc.text(String(d.getDate()).padStart(2, '0'), x + 1, TOP + headH - 2.2); lastX = x; }
      }
      // linhas
      chunk.forEach((r, i) => {
        const ry = bodyTop + i * RH;
        if (i % 2) { fill([250, 250, 252]); doc.rect(ML, ry, CW, RH, 'F'); }
      });
      // faixa da semana + grade semanal
      alpha(0.35, () => { fill(C.yellow); doc.rect(X(weekStart), bodyTop, X(addDays(cutDate, 1)) - X(weekStart), bodyBot - bodyTop, 'F'); });
      for (let d = new Date(t0); d < t1; d = addDays(d, 7)) { stroke(C.line); doc.setLineWidth(0.12); doc.line(X(d), bodyTop, X(d), bodyBot); }
      stroke(C.line); doc.setLineWidth(0.2); doc.line(gx, TOP, gx, bodyBot);
      chunk.forEach((r, i) => {
        const ry = bodyTop + i * RH, ty = ry + RH / 2 + 1.1;
        let x = ML;
        font(isFase(r.t) ? 'bold' : 'normal', 6.3); color(C.gray); doc.text(String(r.n), x + cols[0].w / 2, ty, { align: 'center' }); x += cols[0].w;
        color(C.ink); doc.text(fit(r.t.name, cols[1].w - 3), x + 2, ty); x += cols[1].w;
        font('normal', 6.1); color(C.gray); doc.text(brShort(r.s), x + 2, ty); x += cols[2].w;
        doc.text(brShort(r.e), x + 2, ty); x += cols[3].w;
        font('bold', 6.1); color(STATUS[r.st].c); doc.text(pct0(r.re), x + 2, ty);
        hline(ML, ry + RH, ML + CW, C.line, 0.1);
        if (!r.s || !r.e) return;
        const bx = X(r.s), bw = Math.max(0.8, X(addDays(r.e, 1)) - bx);
        if (isMarco(r.t)) {
          const mx = X(r.s), my = ry + RH / 2;
          fill(C.ink); doc.lines([[1.6, 1.6], [-1.6, 1.6], [-1.6, -1.6]], mx, my - 1.6, [1, 1], 'F', true);
          font('normal', 5.5); color(C.gray); doc.text(brShort(r.s), mx + 2.6, my + 1);
          return;
        }
        const by = ry + 1.5, bh = RH - 3;
        if (isFase(r.t)) { fill(C.ink); doc.rect(bx, by + bh / 2 - 0.7, bw, 1.4, 'F'); return; }
        fill(C.tint); doc.rect(bx, by, bw, bh, 'F');
        fill(STATUS[r.st].c); doc.rect(bx, by, bw * Math.min(100, r.re) / 100, bh, 'F');
        if (r.t.responsible) {
          font('normal', 5.3); color(C.gray);
          const tx = bx + bw + 1.5;
          if (tx + 20 < gx + gw) doc.text(fit(r.t.responsible, 30), tx, ry + RH / 2 + 1);
        }
      });
      // linha de corte
      const cx2 = X(addDays(cutDate, 1));
      stroke(C.red); doc.setLineWidth(0.35); doc.setLineDashPattern([1, 0.8], 0); doc.line(cx2, bodyTop, cx2, bodyBot); doc.setLineDashPattern([], 0);
      // legenda
      const ly = bodyBot + 7.5;
      let lx = ML + 4;
      const leg = (c, label, w = 6) => { fill(c); doc.rect(lx, ly - 2.2, w, 2.8, 'F'); font('normal', 6); color(C.gray); doc.text(label, lx + w + 1.5, ly); lx += w + 4 + doc.getTextWidth(label); };
      leg(C.tint, 'Previsto');
      ['done', 'prog', 'warn', 'late'].forEach(k => leg(STATUS[k].c, 'Realizado - ' + STATUS[k].label.toLowerCase()));
      alpha(0.5, () => { fill(C.yellow); doc.rect(lx, ly - 2.2, 6, 2.8, 'F'); }); font('normal', 6); color(C.gray); doc.text('Semana do relatório', lx + 7.5, ly); lx += 38;
      stroke(C.red); doc.setLineWidth(0.35); doc.setLineDashPattern([1, 0.8], 0); doc.line(lx, ly - 0.8, lx + 6, ly - 0.8); doc.setLineDashPattern([], 0);
      doc.text('Data de corte (' + brShort(cutDate) + ')', lx + 7.5, ly);
    }
  })();

  // ════════════════════════════════════════════════
  // 3. ATIVIDADES (tabela detalhada)
  // ════════════════════════════════════════════════
  (() => {
    const cols = [
      { k: '#', w: 8, a: 'center' }, { k: 'Atividade', w: 82 }, { k: 'Responsável', w: 32 },
      { k: 'Início', w: 17 }, { k: 'Término', w: 17 }, { k: 'Dur. (d.u.)', w: 14, a: 'right' },
      { k: 'Previsto', w: 15, a: 'right' }, { k: 'Real', w: 30 }, { k: 'Desvio', w: 15, a: 'right' },
      { k: 'Situação', w: 25, a: 'center' }, { k: 'Semana', w: 18, a: 'center' },
    ];
    const RH = 7, headH = 8;
    const perPage = Math.floor((BOTTOM - TOP - headH - 14) / RH);
    const pages = Math.max(1, Math.ceil(rows.length / perPage));
    for (let p = 0; p < pages; p++) {
      newPage('table');
      const chunk = rows.slice(p * perPage, (p + 1) * perPage);
      const isLast = p === pages - 1;
      const h = headH + chunk.length * RH + (isLast ? 10 : 0);
      panel(ML, TOP, CW, h);
      fill(C.navy); doc.rect(ML, TOP, CW, headH, 'F');
      font('bold', 6.2); color(C.white);
      let x = ML;
      const colX = [];
      cols.forEach(c => {
        colX.push(x);
        const tx = c.a === 'center' ? x + c.w / 2 : c.a === 'right' ? x + c.w - 2 : x + 2;
        doc.text(c.k.toUpperCase(), tx, TOP + 5.2, { align: c.a || 'left' });
        x += c.w;
      });
      chunk.forEach((r, i) => {
        const ry = TOP + headH + i * RH, ty = ry + 4.6;
        if (isFase(r.t)) { fill(C.bg); doc.rect(ML, ry, CW, RH, 'F'); }
        else if (i % 2) { fill([250, 250, 252]); doc.rect(ML, ry, CW, RH, 'F'); }
        const cell = (ci, txt, opt = {}) => {
          const c = cols[ci], cx = colX[ci];
          const tx = c.a === 'center' ? cx + c.w / 2 : c.a === 'right' ? cx + c.w - 2 : cx + 2;
          doc.text(fit(txt, c.w - 3), tx, ty, { align: c.a || 'left', ...opt });
        };
        font('normal', 6.6); color(C.gray); cell(0, String(r.n));
        font(isFase(r.t) ? 'bold' : 'normal', 6.6); color(C.ink); cell(1, r.t.name + (isMarco(r.t) ? '  (marco)' : ''));
        font('normal', 6.4); color(C.gray); cell(2, r.t.responsible || '-');
        cell(3, br(r.s)); cell(4, br(r.e));
        cell(5, isMarco(r.t) ? '0' : String(r.t.duration || '-'));
        color(C.ink); cell(6, pct0(r.pr));
        // real com barra
        const rx = colX[7] + 2, rw = cols[7].w - 13;
        fill(C.bg); doc.rect(rx, ry + 2.4, rw, 2.4, 'F');
        fill(STATUS[r.st].c); doc.rect(rx, ry + 2.4, rw * Math.min(100, r.re) / 100, 2.4, 'F');
        font('bold', 6.4); color(C.ink); doc.text(pct0(r.re), colX[7] + cols[7].w - 2, ty, { align: 'right' });
        font('bold', 6.4); color(r.dev <= -10 ? C.red : r.dev <= -5 ? C.amber : r.dev > 0 ? C.green : C.gray);
        cell(8, (r.dev > 0 ? '+' : '') + Math.round(r.dev) + ' p.p.');
        if (!isFase(r.t)) pill(colX[9] + 2, ty, r.st, cols[9].w - 4);
        // executada na semana
        const bx = colX[10] + cols[10].w / 2 - 1.6, by = ry + 1.9;
        stroke(r.checked ? C.navy : C.gray2); doc.setLineWidth(0.25);
        if (r.checked) { fill(C.navy); doc.rect(bx, by, 3.2, 3.2, 'FD'); stroke(C.white); doc.setLineWidth(0.45); doc.lines([[0.7, 0.8], [1.3, -1.7]], bx + 0.7, by + 1.7); }
        else doc.rect(bx, by, 3.2, 3.2, 'S');
        hline(ML, ry + RH, ML + CW, C.line, 0.12);
      });
      if (isLast) {
        const ty = TOP + headH + chunk.length * RH + 6.3;
        fill(C.bg); doc.rect(ML + 0.15, ty - 6.1, CW - 0.3, 9.7, 'F');
        font('bold', 6.6); color(C.ink);
        doc.text('TOTAL PONDERADO', colX[1] + 2, ty);
        doc.text(pct1(planPct), colX[6] + cols[6].w - 2, ty, { align: 'right' });
        doc.text(pct1(realPct), colX[7] + cols[7].w - 2, ty, { align: 'right' });
        color(devPct < -5 ? C.red : C.ink); doc.text(pp(devPct), colX[8] + cols[8].w - 2, ty, { align: 'right' });
        color(C.gray); font('normal', 6);
        doc.text(executedWeek.length + ' executada(s)', colX[10] + cols[10].w / 2, ty, { align: 'center' });
      }
      font('normal', 5.8); color(C.gray2);
      doc.text('Previsto: percentual planejado até a data de corte, proporcional aos dias úteis decorridos (feriados nacionais considerados). Desvio = real - previsto. Semana: atividade executada no período do relatório.', ML, BOTTOM - 1.5);
    }
  })();

  // ════════════════════════════════════════════════
  // 4. SEMANA E OCORRÊNCIAS
  // ════════════════════════════════════════════════
  newPage('week');
  (() => {
    const lW = 168, rX = ML + lW + 4, rW = CW - lW - 4;
    // executadas
    const h1 = Math.min(110, Math.max(48, 30 + executedWeek.length * 6));
    panel(ML, TOP, lW, h1, 'Atividades executadas no período', br(weekStart) + ' a ' + br(cutDate));
    const tbl = (x, y, w, list, colsDef, maxRows, empty) => {
      font('bold', 5.9); color(C.gray);
      let cx = x;
      colsDef.forEach(c => { doc.text(c.k.toUpperCase(), c.a === 'right' ? cx + c.w : cx, y, { align: c.a || 'left', charSpace: 0.1 }); cx += c.w; });
      hline(x, y + 1.6, x + w, C.gray2, 0.25);
      let ry = y + 6;
      if (!list.length) { font('normal', 6.6); color(C.gray2); doc.text(empty, x, ry); return; }
      list.slice(0, maxRows).forEach(r => {
        let cx = x;
        colsDef.forEach(c => { c.draw(r, cx, ry, c.w); cx += c.w; });
        hline(x, ry + 2.2, x + w, C.line, 0.12);
        ry += 6;
      });
      if (list.length > maxRows) { font('normal', 5.8); color(C.gray2); doc.text('+ ' + (list.length - maxRows) + ' atividade(s) - ver aba Atividades', x, ry); }
    };
    const txt = (st, sz, c, f = r => '') => (r, x, y, w) => { font(st, sz); color(c); doc.text(fit(f(r), w - 2), x, y); };
    tbl(ML + 4, TOP + 16, lW - 8, executedWeek, [
      { k: '#', w: 8, draw: txt('normal', 6.5, C.gray, r => String(r.n)) },
      { k: 'Atividade', w: 72, draw: txt('normal', 6.5, C.ink, r => r.t.name) },
      { k: 'Responsável', w: 28, draw: txt('normal', 6.3, C.gray, r => r.t.responsible || '-') },
      { k: 'Prev.', w: 12, a: 'right', draw: (r, x, y, w) => { font('normal', 6.5); color(C.gray); doc.text(pct0(r.pr), x + w, y, { align: 'right' }); } },
      { k: 'Real', w: 14, a: 'right', draw: (r, x, y, w) => { font('bold', 6.5); color(C.ink); doc.text(pct0(r.re), x + w, y, { align: 'right' }); } },
      { k: '', w: 24, draw: (r, x, y, w) => pill(x + 3, y, r.st, w - 3) },
    ], Math.floor((h1 - 22) / 6), 'Nenhuma atividade marcada como executada neste período.');

    // próxima semana
    const y2 = TOP + h1 + 4, h2 = BOTTOM - y2;
    panel(ML, y2, lW, h2, 'Programação para a próxima semana', br(nextA) + ' a ' + br(nextB) + '  |  meta = previsto ao fim da semana  |  pendente = término já vencido');
    tbl(ML + 4, y2 + 16, lW - 8, nextWeek, [
      { k: '#', w: 8, draw: txt('normal', 6.5, C.gray, r => String(r.n)) },
      { k: 'Atividade', w: 82, draw: txt('normal', 6.5, C.ink, r => r.t.name) },
      { k: 'Término', w: 22, draw: (r, x, y, w) => { font(r.e < nextA ? 'bold' : 'normal', 6.3); color(r.e < nextA ? C.red : C.gray); doc.text(br(r.e), x, y); } },
      { k: 'Atual', w: 16, a: 'right', draw: (r, x, y, w) => { font('normal', 6.5); color(C.gray); doc.text(pct0(r.re), x + w, y, { align: 'right' }); } },
      { k: 'Meta', w: 16, a: 'right', draw: (r, x, y, w) => { font('bold', 6.5); color(C.navy); doc.text(pct0(plannedAt(r.t, nextB)), x + w, y, { align: 'right' }); } },
      { k: '', w: 16, draw: (r, x, y, w) => { if (r.e < nextA) { font('bold', 5.9); color(C.red); doc.text('PENDENTE', x + w, y, { align: 'right' }); } } },
    ], Math.floor((h2 - 22) / 6), 'Nenhuma atividade programada para o período.');

    // aderência
    const hA = 44;
    panel(rX, TOP, rW, hA, 'Aderência à programação semanal', 'Programadas no período que foram executadas');
    const aC = adherence === null ? C.gray2 : adherence >= 80 ? C.green : adherence >= 60 ? C.amber : C.red;
    ringSeg(rX + 22, TOP + 29, 9, 13, 0, 359.9, C.bg);
    if (adherence) ringSeg(rX + 22, TOP + 29, 9, 13, 0, Math.min(359.9, adherence * 3.6), aC);
    font('bold', 10); color(C.ink); doc.text(adherence === null ? '-' : pct0(adherence), rX + 22, TOP + 30.5, { align: 'center' });
    font('normal', 6.6); color(C.gray);
    const aTxt = plannedWeek.length
      ? adherenceHits + ' de ' + plannedWeek.length + ' atividades programadas para o período foram executadas.' + (executedWeek.length > adherenceHits ? ' ' + (executedWeek.length - adherenceHits) + ' atividade(s) executada(s) fora da programação.' : '')
      : 'Não havia atividades programadas para este período no cronograma.';
    doc.text(doc.splitTextToSize(aTxt, rW - 48), rX + 42, TOP + 22);

    // ocorrências
    const yO = TOP + hA + 4, hO = BOTTOM - yO - 34;
    panel(rX, yO, rW, hO, 'Ocorrências e observações');
    font('normal', 7); color(C.ink);
    const obs = (rel.observations || '').trim();
    const lines = obs ? doc.splitTextToSize(obs, rW - 10) : [];
    const maxL = Math.floor((hO - 14) / 3.6);
    if (lines.length > maxL) { lines.length = maxL; lines[maxL - 1] = fit(lines[maxL - 1], rW - 16) + ' (continua)'; }
    if (lines.length) doc.text(lines, rX + 5, yO + 13, { lineHeightFactor: 1.45 });
    else { color(C.gray2); doc.text('Sem ocorrências registradas no período.', rX + 5, yO + 13); }

    // assinaturas
    const yS = BOTTOM - 30;
    panel(rX, yS, rW, 30, 'Validação');
    const sw = (rW - 15) / 2;
    [[supervisorName(), 'Responsável técnico'], ['', 'Fiscalização / cliente']].forEach(([name, role], i) => {
      const sx = rX + 5 + i * (sw + 5);
      hline(sx, yS + 21, sx + sw, C.gray, 0.3);
      font('bold', 6.4); color(C.ink); if (name) doc.text(fit(name, sw), sx, yS + 24.5);
      font('normal', 5.9); color(C.gray); doc.text(role, sx, name ? yS + 27.5 : yS + 24.5);
    });
  })();
  function supervisorName() { return state.supervisorName || ''; }

  // ════════════════════════════════════════════════
  // Cabeçalho, abas navegáveis e rodapé em todas as páginas
  // ════════════════════════════════════════════════
  const TABS = [
    { key: 'overview', label: 'Visão geral' },
    { key: 'gantt', label: 'Cronograma' },
    { key: 'table', label: 'Atividades' },
    { key: 'week', label: 'Semana e ocorrências' },
  ];
  const total = doc.getNumberOfPages();
  const emissao = new Date();
  for (let p = 1; p <= total; p++) {
    doc.setPage(p);
    const active = pageSection[p];
    // faixa superior
    fill(C.navy); doc.rect(0, 0, PW, 15, 'F');
    fill(C.yellow); doc.rect(0, 15, PW, 0.7, 'F');
    if (typeof HAGANA_LOGO_B64 !== 'undefined' && HAGANA_LOGO_B64) {
      try { doc.addImage(HAGANA_LOGO_B64, 'PNG', ML, 2, 9.4, 11, 'hagana', 'FAST'); } catch (e) {}
    }
    font('bold', 10.5); color(C.white); doc.text('RELATÓRIO SEMANAL DE ACOMPANHAMENTO DE OBRA', ML + 13, 7.2, { charSpace: 0.2 });
    font('normal', 7.2); doc.setTextColor(200, 202, 232); doc.text(fit((state.projectName || 'Projeto').toUpperCase(), 150), ML + 13, 11.8);
    font('bold', 9); color(C.white); doc.text('Relatório nº ' + reportNo, PW - MR, 7.2, { align: 'right' });
    font('normal', 7); doc.setTextColor(200, 202, 232); doc.text('Período ' + br(weekStart) + ' a ' + br(cutDate), PW - MR, 11.8, { align: 'right' });
    // abas
    fill(C.white); doc.rect(0, 15.7, PW, 7.5, 'F');
    hline(0, 23.2, PW, C.line, 0.25);
    let tx = ML;
    TABS.forEach(tab => {
      const on = tab.key === active;
      font(on ? 'bold' : 'normal', 7.2);
      const w = doc.getTextWidth(tab.label) + 8;
      if (on) { fill(C.bg); doc.rect(tx, 15.7, w, 7.5, 'F'); fill(C.navy); doc.rect(tx, 22.4, w, 0.8, 'F'); }
      color(on ? C.navy : C.gray); doc.text(tab.label, tx + 4, 20.6);
      if (sections[tab.key] && !on) doc.link(tx, 15.7, w, 7.5, { pageNumber: sections[tab.key] });
      tx += w;
    });
    font('normal', 6.2); color(C.gray2);
    doc.text('Data de corte ' + br(cutDate) + '   |   Emitido em ' + br(emissao), PW - MR, 20.6, { align: 'right' });
    // rodapé
    hline(ML, PH - 8, PW - MR, C.line, 0.25);
    font('normal', 6); color(C.gray2);
    doc.text('Hagana Tecnologia  |  Oreon Soluções', ML, PH - 4.5);
    if (supervisorName()) doc.text('Responsável técnico: ' + supervisorName(), PW / 2, PH - 4.5, { align: 'center' });
    doc.text('Página ' + p + ' de ' + total, PW - MR, PH - 4.5, { align: 'right' });
  }

  doc.setPage(1);
  pendLinks.forEach(([x, y, w, h, key]) => { if (sections[key]) doc.link(x, y, w, h, { pageNumber: sections[key] }); });
  if (sections.gantt) doc.link(ML, TOP + 27, 178, 78, { pageNumber: sections.gantt });

  // Marcadores (painel lateral do leitor de PDF)
  try {
    TABS.forEach(tab => { if (sections[tab.key]) doc.outline.add(null, tab.label, { pageNumber: sections[tab.key] }); });
  } catch (e) {}
  doc.setProperties({
    title: 'Relatório Semanal nº ' + reportNo + ' - ' + (state.projectName || ''),
    subject: 'Acompanhamento de obra - ' + br(weekStart) + ' a ' + br(cutDate),
    author: supervisorName() || 'Hagana Tecnologia',
    creator: 'Cronograma de Obras - Hagana Tecnologia',
  });
  try { doc.setDisplayMode('fullwidth', 'single', 'UseOutlines'); } catch (e) {}

  const safe = (state.projectName || 'Projeto').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9]+/g, '_').replace(/^_|_$/g, '');
  doc.save(`Relatorio_Semanal_${reportNo}_${safe}_${(rel.weekStart || '').replace(/-/g, '')}.pdf`);
  toast('📄 Relatório PDF exportado!');
}

// ── Relatório para o cliente: uma página, leitura rápida ──
function exportRelatorioClientePDF(rel) {
  if (!window.jspdf || !window.jspdf.jsPDF) {
    toast('Biblioteca de PDF não carregou. Verifique a conexão com a internet.', 3500);
    return;
  }
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ orientation: 'l', unit: 'mm', format: 'a4' });
  const PW = 297, PH = 210, ML = 14, MR = 14, CW = PW - ML - MR;

  const C = {
    navy: [39, 40, 103], navy2: [72, 76, 160], ink: [28, 30, 44], gray: [96, 100, 116], gray2: [150, 154, 168],
    line: [224, 226, 233], bg: [245, 246, 249], white: [255, 255, 255], yellow: [253, 234, 0],
    green: [22, 135, 72], greenL: [226, 243, 233], amber: [196, 124, 0], amberL: [253, 243, 220],
    red: [192, 44, 44], redL: [250, 229, 229], navyL: [230, 231, 245],
  };
  const fill = c => doc.setFillColor(c[0], c[1], c[2]);
  const stroke = c => doc.setDrawColor(c[0], c[1], c[2]);
  const color = c => doc.setTextColor(c[0], c[1], c[2]);
  const font = (st, sz) => { doc.setFont('helvetica', st); doc.setFontSize(sz); };
  const fit = (txt, w) => { txt = String(txt || ''); if (doc.getTextWidth(txt) <= w) return txt; while (txt.length > 1 && doc.getTextWidth(txt + '...') > w) txt = txt.slice(0, -1); return txt.trimEnd() + '...'; };
  const cap = s => { s = String(s || '').toLowerCase(); return s.charAt(0).toUpperCase() + s.slice(1); };
  const nice = s => { const t = String(s || ''); return t === t.toUpperCase() ? cap(t).replace(/\b(qdc|cftv|dvr|nvr|ups|ti)\b/gi, m => m.toUpperCase()) : t; };

  // ── Datas e dias úteis ──
  const dayOf = iso => { if (!iso) return null; const d = new Date(iso); d.setHours(0, 0, 0, 0); return d; };
  const parseYMD = s => { const [y, m, d] = s.split('-').map(Number); return new Date(y, m - 1, d); };
  const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x; };
  const br = d => d ? d.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' }) : '-';
  const brShort = d => d ? d.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }) : '-';
  const brLong = d => d ? d.toLocaleDateString('pt-BR', { day: 'numeric', month: 'long', year: 'numeric' }) : '-';

  const tasks = state.tasks.slice();
  const starts = tasks.map(t => dayOf(t.start)).filter(Boolean), ends = tasks.map(t => dayOf(t.end)).filter(Boolean);
  const projStart = starts.length ? new Date(Math.min(...starts)) : parseYMD(rel.weekStart);
  const projEnd = ends.length ? new Date(Math.max(...ends)) : parseYMD(rel.weekEnd);
  const weekStart = parseYMD(rel.weekStart), cutDate = parseYMD(rel.weekEnd);
  const years = []; for (let y = projStart.getFullYear() - 1; y <= projEnd.getFullYear() + 1; y++) years.push(y);
  const HOL = buildHolidaySet(years);
  const isWork = d => !isWeekend(d) && !HOL.has(dateKey(new Date(d.getFullYear(), d.getMonth(), d.getDate(), 12)));
  const workdays = (a, b) => { if (!a || !b || b < a) return 0; let n = 0; const d = new Date(a); while (d <= b) { if (isWork(d)) n++; d.setDate(d.getDate() + 1); } return n; };

  // ── Histórico (mesma regra do relatório completo) ──
  const rels = [...state.relatorios].sort((a, b) => a.weekStart.localeCompare(b.weekStart));
  const relIdx = rels.findIndex(r => r.id === rel.id);
  if (relIdx === rels.length - 1 || !rel.snapshot) {
    rel.snapshot = { takenAt: new Date().toISOString(), pct: {} };
    tasks.forEach(t => { rel.snapshot.pct[t.id] = t.percentComplete || 0; });
    save();
  }
  const reportNo = String(relIdx + 1).padStart(2, '0');
  const realOf = t => { const v = rel.snapshot && rel.snapshot.pct ? rel.snapshot.pct[t.id] : undefined; return v === undefined ? (t.percentComplete || 0) : v; };

  const isFase = t => t.taskType === 'fase', isMarco = t => t.taskType === 'marco';
  const weightOf = t => isFase(t) || isMarco(t) ? 0 : Math.max(Number(t.duration) || 0, 1);
  let totalW = tasks.reduce((s, t) => s + weightOf(t), 0);
  const W = t => totalW ? weightOf(t) : 1; if (!totalW) totalW = tasks.length || 1;
  const plannedAt = (t, ref) => { const s = dayOf(t.start), e = dayOf(t.end); if (!s || !e || ref < s) return 0; if (ref >= e) return 100; const tot = workdays(s, e); return tot ? Math.min(100, workdays(s, ref) / tot * 100) : 0; };
  const weighted = fn => tasks.reduce((s, t) => s + W(t) * fn(t), 0) / totalW;
  const realPct = weighted(realOf), planPct = weighted(t => plannedAt(t, cutDate)), dev = realPct - planPct;
  const remainingWD = cutDate < projEnd ? workdays(addDays(cutDate, 1), projEnd) : 0;

  const steps = tasks.filter(t => !isFase(t)).map(t => {
    const re = realOf(t), pr = plannedAt(t, cutDate), s = dayOf(t.start), e = dayOf(t.end);
    let st = re >= 100 ? 'done' : (pr - re >= 10 ? 'late' : re > 0 ? 'prog' : (pr > 0 ? 'late' : 'todo'));
    return { t, re, pr, s, e, st, checked: !!(rel.taskChecks && rel.taskChecks[t.id]) };
  });
  const nDone = steps.filter(x => x.st === 'done').length;

  let verdict;
  if (dev > 2)        verdict = { tag: 'ADIANTADA',      c: C.green, bg: C.greenL, txt: 'A obra está à frente do planejado.' };
  else if (dev >= -2) verdict = { tag: 'NO PRAZO',       c: C.green, bg: C.greenL, txt: 'A obra está dentro do planejado.' };
  else if (dev >= -8) verdict = { tag: 'PEQUENO ATRASO', c: C.amber, bg: C.amberL, txt: 'A obra está um pouco abaixo do previsto para esta data.' };
  else                verdict = { tag: 'ATRASADA',       c: C.red,   bg: C.redL,   txt: 'A obra está abaixo do previsto para esta data.' };
  if (realPct >= 99.5) verdict = { tag: 'CONCLUÍDA', c: C.green, bg: C.greenL, txt: 'Todas as etapas foram concluídas.' };

  const doneWeek = steps.filter(x => x.checked);
  const nextA = addDays(cutDate, 1), nextB = addDays(cutDate, 7);
  const nextWeek = steps.filter(x => x.re < 100 && x.s && x.e && ((x.s <= nextB && x.e >= nextA) || x.e < nextA));

  // ── Fundo e cabeçalho ──
  fill(C.bg); doc.rect(0, 0, PW, PH, 'F');
  fill(C.navy); doc.rect(0, 0, PW, 20, 'F');
  fill(C.yellow); doc.rect(0, 20, PW, 0.8, 'F');
  if (typeof HAGANA_LOGO_B64 !== 'undefined' && HAGANA_LOGO_B64) { try { doc.addImage(HAGANA_LOGO_B64, 'PNG', ML, 3, 10.1, 14, 'hagana', 'FAST'); } catch (e) {} }
  font('bold', 13); color(C.white); doc.text(fit((state.projectName || 'Obra').toUpperCase(), 170), ML + 15, 10);
  font('normal', 8); doc.setTextColor(200, 202, 232); doc.text('Relatório semanal de andamento da obra', ML + 15, 15.2);
  font('bold', 10); color(C.white); doc.text('Semana de ' + brShort(weekStart) + ' a ' + br(cutDate), PW - MR, 10, { align: 'right' });
  font('normal', 8); doc.setTextColor(200, 202, 232); doc.text('Relatório nº ' + reportNo, PW - MR, 15.2, { align: 'right' });

  // ── Faixa principal: andamento, situação, entrega ──
  let y = 28;
  const heroH = 44;
  fill(C.white); stroke(C.line); doc.setLineWidth(0.25); doc.rect(ML, y, CW, heroH, 'FD');
  // andamento
  font('bold', 7.5); color(C.gray); doc.text('ANDAMENTO DA OBRA', ML + 8, y + 10, { charSpace: 0.3 });
  font('bold', 38); color(C.ink); const bigTxt = Math.round(realPct) + '%'; doc.text(bigTxt, ML + 8, y + 27);
  const bw = doc.getTextWidth(bigTxt);
  font('normal', 10); color(C.gray); doc.text('concluída', ML + 10 + bw, y + 27);
  // barra de progresso
  const bx = ML + 8, by = y + 33, bW = 150, bH = 4.2;
  fill(C.line); doc.roundedRect(bx, by, bW, bH, 2.1, 2.1, 'F');
  fill(verdict.c); doc.roundedRect(bx, by, Math.max(bH, bW * Math.min(100, realPct) / 100), bH, 2.1, 2.1, 'F');
  const px = bx + bW * Math.min(100, planPct) / 100;
  fill(C.ink); doc.rect(px - 0.35, by - 1.8, 0.7, bH + 3.6, 'F');
  font('normal', 6.8); color(C.gray); doc.text('previsto para esta data: ' + Math.round(planPct) + '%', Math.min(px, bx + bW - 30), by + bH + 5, { align: px > bx + bW - 30 ? 'left' : 'center' });

  // separadores
  stroke(C.line); doc.setLineWidth(0.25);
  const c2 = ML + 170, c3 = ML + 226;
  doc.line(c2, y + 7, c2, y + heroH - 7); doc.line(c3, y + 7, c3, y + heroH - 7);
  // situação
  font('bold', 7.5); color(C.gray); doc.text('SITUAÇÃO', c2 + 7, y + 10, { charSpace: 0.3 });
  font('bold', 9); const tagW = doc.getTextWidth(verdict.tag) + 8;
  fill(verdict.bg); doc.roundedRect(c2 + 7, y + 14.5, tagW, 7, 1.2, 1.2, 'F');
  color(verdict.c); doc.text(verdict.tag, c2 + 11, y + 19.4);
  font('normal', 8); color(C.ink); doc.text(doc.splitTextToSize(verdict.txt, c3 - c2 - 14), c2 + 7, y + 28.5, { lineHeightFactor: 1.35 });
  font('normal', 7.2); color(C.gray); doc.text(nDone + ' de ' + steps.length + ' etapas concluídas', c2 + 7, y + heroH - 6);
  // entrega
  font('bold', 7.5); color(C.gray); doc.text('ENTREGA PREVISTA', c3 + 7, y + 10, { charSpace: 0.3 });
  font('bold', 17); color(C.ink); doc.text(br(projEnd), c3 + 7, y + 22.5);
  font('normal', 8); color(C.gray);
  doc.text(realPct >= 99.5 ? 'Obra concluída' : remainingWD + ' dias úteis restantes', c3 + 7, y + 29);
  font('normal', 7.2); doc.text('Início em ' + br(projStart), c3 + 7, y + heroH - 6);

  // ── Etapas da obra ──
  y += heroH + 5;
  const colL = 168, bottom = PH - 14, lh = bottom - y;
  fill(C.white); stroke(C.line); doc.rect(ML, y, colL, lh, 'FD');
  font('bold', 10); color(C.ink); doc.text('Etapas da obra', ML + 8, y + 10);
  const ST = {
    done: { label: 'Concluída', c: C.green },
    prog: { label: 'Em andamento', c: C.navy2 },
    late: { label: 'Em atraso', c: C.red },
    todo: { label: 'Prevista', c: C.gray2 },
  };
  // legenda
  let lgx = ML + colL - 8;
  ['todo', 'late', 'prog', 'done'].forEach(k => {
    font('normal', 6.8); const w = doc.getTextWidth(ST[k].label);
    lgx -= w; color(C.gray); doc.text(ST[k].label, lgx, y + 10);
    lgx -= 4.5; fill(ST[k].c); doc.circle(lgx + 1.4, y + 9, 1.4, 'F'); lgx -= 5;
  });
  stroke(C.line); doc.line(ML + 8, y + 14, ML + colL - 8, y + 14);

  const listTop = y + 16, listBot = y + lh - 4;
  const maxRows = Math.floor((listBot - listTop) / 7.2);
  let shown = steps;
  if (steps.length > maxRows) {
    // prioriza o que está acontecendo: em atraso / andamento, depois próximas, depois concluídas recentes
    const firstOpen = Math.max(0, steps.findIndex(s => s.st !== 'done'));
    const startIdx = Math.max(0, Math.min(firstOpen - 1, steps.length - (maxRows - 1)));
    shown = steps.slice(startIdx, startIdx + maxRows - 1);
  }
  const rowH = Math.min(11, (listBot - listTop) / Math.max(shown.length + (shown.length < steps.length ? 1 : 0), 1));
  const nameW = 86, stateX = ML + 8 + 8 + nameW + 6;
  shown.forEach((s, i) => {
    const ry = listTop + i * rowH, cy = ry + rowH / 2;
    const sc = ST[s.st].c;
    // linha vertical de ligação
    if (i < shown.length - 1) { stroke(C.line); doc.setLineWidth(0.5); doc.line(ML + 11, cy + 2.4, ML + 11, cy + rowH - 2.4); }
    // marcador
    if (s.st === 'done') {
      fill(sc); doc.circle(ML + 11, cy, 2.2, 'F');
      stroke(C.white); doc.setLineWidth(0.55); doc.lines([[0.8, 0.8], [1.6, -1.8]], ML + 9.9, cy + 0.1);
    } else if (s.st === 'todo') {
      fill(C.white); stroke(C.gray2); doc.setLineWidth(0.45); doc.circle(ML + 11, cy, 2.1, 'FD');
    } else {
      fill(C.white); stroke(sc); doc.setLineWidth(0.6); doc.circle(ML + 11, cy, 2.1, 'FD');
      fill(sc); doc.circle(ML + 11, cy, 1.05, 'F');
    }
    // nome
    font(s.st === 'prog' || s.st === 'late' ? 'bold' : 'normal', 8.2); color(s.st === 'todo' ? C.gray : C.ink);
    doc.text(fit(nice(s.t.name), nameW), ML + 16, cy + 1.2);
    // estado
    if (s.st === 'done') {
      font('normal', 7.6); color(C.green); doc.text('Concluída', stateX, cy + 1.2);
      font('normal', 7); color(C.gray2); doc.text(brShort(s.e), ML + colL - 8, cy + 1.2, { align: 'right' });
    } else if (s.st === 'todo') {
      font('normal', 7.6); color(C.gray); doc.text('Início previsto em ' + brShort(s.s), stateX, cy + 1.2);
      font('normal', 7); color(C.gray2); doc.text(brShort(s.s) + ' a ' + brShort(s.e), ML + colL - 8, cy + 1.2, { align: 'right' });
    } else {
      const mw = 22;
      fill(C.line); doc.roundedRect(stateX, cy - 1.1, mw, 2.2, 1.1, 1.1, 'F');
      if (s.re > 0) { fill(sc); doc.roundedRect(stateX, cy - 1.1, Math.max(2.2, mw * s.re / 100), 2.2, 1.1, 1.1, 'F'); }
      font('bold', 7.6); color(sc); doc.text(Math.round(s.re) + '%', stateX + mw + 3, cy + 1.2);
      font('normal', 7); color(s.st === 'late' ? C.red : C.gray2);
      doc.text(s.st === 'late' ? (s.e < cutDate ? 'prazo era ' + brShort(s.e) : 'término ' + brShort(s.e)) : 'término ' + brShort(s.e), ML + colL - 8, cy + 1.2, { align: 'right' });
    }
  });
  if (shown.length < steps.length) {
    font('italic', 7); color(C.gray2);
    doc.text('Mostrando ' + shown.length + ' de ' + steps.length + ' etapas. Lista completa no relatório detalhado.', ML + 16, listTop + shown.length * rowH + rowH / 2 + 1);
  }

  // ── Coluna da direita ──
  const rx = ML + colL + 5, rw = CW - colL - 5;
  const box = (by0, h, title) => {
    fill(C.white); stroke(C.line); doc.setLineWidth(0.25); doc.rect(rx, by0, rw, h, 'FD');
    font('bold', 10); color(C.ink); doc.text(title, rx + 7, by0 + 10);
  };
  const obs = (rel.observations || '').trim();
  const RL = 5.6, CAP = obs.length > 180 ? 3 : 4;
  const rowsOf = list => Math.max(1, Math.min(list.length, CAP));
  const bullets = (list, y0, emptyTxt, dotC, metaFn) => {
    let yy = y0;
    if (!list.length) { font('normal', 8); color(C.gray2); doc.text(emptyTxt, rx + 7, yy); return; }
    const show = list.length > CAP ? CAP - 1 : list.length;
    list.slice(0, show).forEach(s => {
      fill(dotC(s)); doc.circle(rx + 8.2, yy - 1.1, 0.9, 'F');
      font('normal', 8); color(C.ink); doc.text(fit(nice(s.t.name), rw - 36), rx + 12, yy);
      font('normal', 7.2); color(C.gray); doc.text(metaFn(s), rx + rw - 7, yy, { align: 'right' });
      yy += RL;
    });
    if (list.length > CAP) { font('italic', 7); color(C.gray2); doc.text('e mais ' + (list.length - show) + ' etapa(s)', rx + 12, yy); }
  };
  const sub = (y0, label, right) => {
    font('bold', 7); color(C.gray); doc.text(label, rx + 7, y0, { charSpace: 0.25 });
    if (right) { font('normal', 7); color(C.gray2); doc.text(right, rx + rw - 7, y0, { align: 'right' }); }
  };

  const hWeek = 15 + 6 + rowsOf(doneWeek) * RL + 5 + 6 + rowsOf(nextWeek) * RL + 2;
  let yy = y;
  box(yy, hWeek, 'Nesta semana');
  let sy = yy + 17;
  sub(sy, 'O QUE FOI FEITO', brShort(weekStart) + ' a ' + brShort(cutDate)); sy += 6;
  bullets(doneWeek, sy, 'Sem atividades registradas no período.', s => s.re >= 100 ? C.green : C.navy2, s => s.re >= 100 ? 'concluída' : Math.round(s.re) + '% concluída');
  sy += rowsOf(doneWeek) * RL + 3;
  stroke(C.line); doc.setLineWidth(0.2); doc.line(rx + 7, sy - 2, rx + rw - 7, sy - 2);
  sy += 4;
  sub(sy, 'PRÓXIMA SEMANA', brShort(nextA) + ' a ' + brShort(nextB)); sy += 6;
  bullets(nextWeek, sy, 'Nenhuma etapa programada.', s => s.e < nextA ? C.red : C.navy2, s => s.e < nextA ? 'atrasada' : (s.s > cutDate ? 'início ' + brShort(s.s) : 'continua'));
  yy += hWeek + 4;
  const hObs = bottom - yy;
  if (hObs > 22) {
    box(yy, hObs, 'Observações');
    font('normal', 8); color(obs ? C.ink : C.gray2);
    let lines = obs ? doc.splitTextToSize(obs, rw - 14) : ['Sem ocorrências no período.'];
    const maxL = Math.floor((hObs - 21) / 4.23) + 1;
    if (lines.length > maxL) { lines = lines.slice(0, maxL); lines[maxL - 1] = fit(lines[maxL - 1], rw - 20) + ' (...)'; }
    doc.text(lines, rx + 7, yy + 18, { lineHeightFactor: 1.5 });
  }

  // ── Rodapé ──
  font('normal', 7); color(C.gray2);
  const resp = state.supervisorName ? 'Responsável técnico: ' + state.supervisorName + '   |   ' : '';
  doc.text(resp + 'Hagana Tecnologia  |  Oreon Soluções', ML, PH - 6);
  doc.text('Emitido em ' + brLong(new Date()), PW - MR, PH - 6, { align: 'right' });

  doc.setProperties({ title: 'Relatório semanal nº ' + reportNo + ' - ' + (state.projectName || ''), author: state.supervisorName || 'Hagana Tecnologia', creator: 'Oreon Cronograma' });
  const safe = (state.projectName || 'Obra').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9]+/g, '_').replace(/^_|_$/g, '');
  doc.save(`Relatorio_${reportNo}_${safe}_${(rel.weekStart || '').replace(/-/g, '')}.pdf`);
  toast('📄 Relatório do cliente exportado!');
}

// ── Boot ──
load();
render();

// Scroll inicial para início do projeto
requestAnimationFrame(() => {
  const starts = state.tasks.map(t=>t.start).filter(Boolean).map(x=>new Date(x));
  if (starts.length) ganttBodyWrap.scrollLeft = 0;
});
